/// Parse a color value from the beginning of the string.
/// Returns (color_string, remaining_string).
fn parse_color_value(s: &str) -> Result<(String, &str), String> {
    // Could be: name (word chars), number (digits or 0x...), or r,g,b triple
    // r,g,b can be decimal or hex (0x...)

    // Check if it's potentially an RGB triple (contains commas)
    // We need to parse: "r,g,b:rest" or "r,g,b" (end of string)

    // Split on ':' and check if the first part looks like an RGB triple
    let first_colon = s.find(':');
    let candidate = match first_colon {
        Some(pos) => &s[..pos],
        None => s,
    };

    // Check if candidate is "r,g,b" format (with possible hex values like 0xff)
    if candidate.contains(',') {
        // It's an RGB triple
        let rest = match first_colon {
            Some(pos) => &s[pos+1..],
            None => "",
        };
        return Ok((candidate.to_string(), rest));
    }

    // It's a simple name or number
    let rest = match first_colon {
        Some(pos) => &s[pos+1..],
        None => "",
    };
    Ok((candidate.to_string(), rest))
}

fn parse_color(s: &str) -> Result<ColorSpec, String> {
    if s == "none" {
        return Ok(ColorSpec::None);
    }

    // Named colors
    match s {
        "black" => return Ok(ColorSpec::Ansi(0)),
        "red" => return Ok(ColorSpec::Ansi(1)),
        "green" => return Ok(ColorSpec::Ansi(2)),
        "yellow" => return Ok(ColorSpec::Ansi(3)),
        "blue" => return Ok(ColorSpec::Ansi(4)),
        "magenta" => return Ok(ColorSpec::Ansi(5)),
        "cyan" => return Ok(ColorSpec::Ansi(6)),
        "white" => return Ok(ColorSpec::Ansi(7)),
        _ => {}
    }

    // RGB triple?
    if s.contains(',') {
        let parts: Vec<&str> = s.split(',').collect();
        if parts.len() == 3 {
            let r = parse_u8_or_hex(parts[0])
                .ok_or_else(|| format!("unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{}'", s))?;
            let g = parse_u8_or_hex(parts[1])
                .ok_or_else(|| format!("unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{}'", s))?;
            let b = parse_u8_or_hex(parts[2])
                .ok_or_else(|| format!("unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{}'", s))?;
            return Ok(ColorSpec::Rgb(r, g, b));
        } else {
            return Err(format!("unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{}'", s));
        }
    }

    // Single number (decimal or hex)
    if let Some(n) = parse_u8_or_hex_full(s) {
        return Ok(ColorSpec::Ansi256(n));
    }

    Err(format!(
        "unexpected color value: unrecognized color name '{}'. Choose from: black, blue, green, red, cyan, magenta, yellow, white",
        s
    ))
}

fn parse_u8_or_hex(s: &str) -> Option<u8> {
    let s = s.trim();
    if s.starts_with("0x") || s.starts_with("0X") {
        u8::from_str_radix(&s[2..], 16).ok()
    } else {
        let n: u16 = s.parse().ok()?;
        if n <= 255 { Some(n as u8) } else { None }
    }
}

fn parse_u8_or_hex_full(s: &str) -> Option<u8> {
    let s = s.trim();
    if s.starts_with("0x") || s.starts_with("0X") {
        u8::from_str_radix(&s[2..], 16).ok()
    } else {
        // Must be a decimal number 0-255
        let n: u64 = s.parse().ok()?;
        if n <= 255 { Some(n as u8) } else { None }
    }
}

/// Face set
struct Faces {
    added: Face,
    removed: Face,
    refine_added: Face,
    refine_removed: Face,
}

impl Faces {
    fn default() -> Self {
        Faces {
            added: default_added(),
            removed: default_removed(),
            refine_added: default_refine_added(),
            refine_removed: default_refine_removed(),
        }
    }
}

/// Line number display mode
#[derive(Debug, Clone, PartialEq)]
enum LineNumberMode {
    None,
    Compact,
    Aligned,
}

/// A token in a diff line
#[derive(Debug, Clone, PartialEq)]
struct Token {
    text: String,
    is_ws: bool,
}

/// Tokenize a line into alternating whitespace/non-whitespace runs
fn tokenize(s: &str) -> Vec<Token> {
    let mut tokens = Vec::new();
    let mut current = String::new();
    let mut current_is_ws = None;

    for c in s.chars() {
        let is_ws = c.is_whitespace();
        match current_is_ws {
            None => {
                current.push(c);
                current_is_ws = Some(is_ws);
            }
            Some(cur_ws) if cur_ws == is_ws => {
                current.push(c);
            }
            Some(_) => {
                tokens.push(Token { text: current.clone(), is_ws: current_is_ws.unwrap() });
                current = String::new();
                current.push(c);
                current_is_ws = Some(is_ws);
            }
        }
    }
    if !current.is_empty() {
        tokens.push(Token { text: current, is_ws: current_is_ws.unwrap() });
    }
    tokens
}

/// LCS result: for each token in seq1, is it in LCS? Same for seq2.
/// Returns (in_lcs_seq1, in_lcs_seq2) where true means "this token is in the LCS"
fn compute_lcs(seq1: &[Token], seq2: &[Token]) -> (Vec<bool>, Vec<bool>) {
    let n = seq1.len();
    let m = seq2.len();

    // Build LCS table
    let mut dp = vec![vec![0usize; m + 1]; n + 1];
    for i in 1..=n {
        for j in 1..=m {
            if seq1[i-1].text == seq2[j-1].text {
                dp[i][j] = dp[i-1][j-1] + 1;
            } else {
                dp[i][j] = dp[i-1][j].max(dp[i][j-1]);
            }
        }
    }

    // Backtrack to find the LCS
    let mut in_lcs1 = vec![false; n];
    let mut in_lcs2 = vec![false; m];
    let mut i = n;
    let mut j = m;
    while i > 0 && j > 0 {
        if seq1[i-1].text == seq2[j-1].text {
            in_lcs1[i-1] = true;
            in_lcs2[j-1] = true;
            i -= 1;
            j -= 1;
        } else if dp[i-1][j] >= dp[i][j-1] {
            i -= 1;
        } else {
            j -= 1;
        }
    }

    (in_lcs1, in_lcs2)
}

/// Segment for display: common or unique
#[derive(Debug, Clone)]
enum Segment {
    Common(String),
    UniqueRemoved(String),
    UniqueAdded(String),
}

/// Given a removed line and added line, compute display segments for each
fn diff_lines(removed: &str, added: &str) -> (Vec<Segment>, Vec<Segment>) {
    let tokens_rm = tokenize(removed);
    let tokens_add = tokenize(added);

    let (lcs_rm, lcs_add) = compute_lcs(&tokens_rm, &tokens_add);

    // Build segments for removed line
    let mut rm_segs: Vec<Segment> = Vec::new();
    for (i, tok) in tokens_rm.iter().enumerate() {
        if lcs_rm[i] {
            // Common token - merge with previous common if possible
            if let Some(Segment::Common(ref mut s)) = rm_segs.last_mut() {
                s.push_str(&tok.text);
            } else {
                rm_segs.push(Segment::Common(tok.text.clone()));
            }
        } else {
            // Unique token - merge with previous unique if possible
            if let Some(Segment::UniqueRemoved(ref mut s)) = rm_segs.last_mut() {
                s.push_str(&tok.text);
            } else {
                rm_segs.push(Segment::UniqueRemoved(tok.text.clone()));
            }
        }
    }

    // Build segments for added line
    let mut add_segs: Vec<Segment> = Vec::new();
    for (i, tok) in tokens_add.iter().enumerate() {
        if lcs_add[i] {
            if let Some(Segment::Common(ref mut s)) = add_segs.last_mut() {
                s.push_str(&tok.text);
            } else {
                add_segs.push(Segment::Common(tok.text.clone()));
            }
        } else {
            if let Some(Segment::UniqueAdded(ref mut s)) = add_segs.last_mut() {
                s.push_str(&tok.text);
            } else {
                add_segs.push(Segment::UniqueAdded(tok.text.clone()));
            }
        }
    }

    (rm_segs, add_segs)
}

/// Write a single line segment to output
fn write_segment(out: &mut Vec<u8>, seg: &Segment, face: &Face, refine_face: &Face) {
    match seg {
        Segment::Common(s) => {
            out.extend_from_slice(b"\x1b[0m");
            face.write_ansi(out);
            out.extend_from_slice(s.as_bytes());
            out.extend_from_slice(b"\x1b[0m");
        }
        Segment::UniqueRemoved(s) | Segment::UniqueAdded(s) => {
            out.extend_from_slice(b"\x1b[0m");
            refine_face.write_ansi(out);
            out.extend_from_slice(s.as_bytes());
            out.extend_from_slice(b"\x1b[0m");
        }
    }
}

/// Write a complete diff line (removed or added) with highlighting
fn write_diff_line(
    out: &mut Vec<u8>,
    prefix: u8,
    content: &str,
    segs: &[Segment],
    face: &Face,
    refine_face: &Face,
    line_num_str: Option<&str>,
    mode: &LineNumberMode,
) {
    // Write line number if present
    if let Some(num_str) = line_num_str {
        out.extend_from_slice(b"\x1b[0m");
        face.write_ansi(out);
        out.extend_from_slice(num_str.as_bytes());
        out.extend_from_slice(b"\x1b[0m");
        if *mode == LineNumberMode::Aligned {
            out.push(b'\t');
        }
    }

    // Write line prefix
    out.extend_from_slice(b"\x1b[0m");
    face.write_ansi(out);
    out.push(prefix);
    out.extend_from_slice(b"\x1b[0m");

    if segs.is_empty() {
        // Empty content: write trailing refine background
        // This is the special case: ESC[41m for empty lines
        out.extend_from_slice(b"\x1b[0m");
        out.extend_from_slice(b"\x1b[41m");
        out.extend_from_slice(b"\x1b[0m");
    } else {
        // Check if first segment is common whitespace-only (for prefix merging)
        // Actually the first segment is just output normally, not merged with prefix

        // Process segments
        let last_idx = segs.len() - 1;
        for (i, seg) in segs.iter().enumerate() {
            write_segment(out, seg, face, refine_face);

            // If this is the last segment and it's unique, add trailing face RST
            if i == last_idx {
                match seg {
                    Segment::UniqueRemoved(_) | Segment::UniqueAdded(_) => {
                        out.extend_from_slice(b"\x1b[0m");
                        face.write_ansi(out);
                        out.extend_from_slice(b"\x1b[0m");
                    }
                    _ => {}
                }
            }
        }
    }

    out.push(b'\n');
}

/// Write a context line
fn write_context_line(
    out: &mut Vec<u8>,
    content: &str,
    line_num_str: Option<&str>,
    mode: &LineNumberMode,
) {
    if let Some(num_str) = line_num_str {
        out.extend_from_slice(num_str.as_bytes());
        out.extend_from_slice(b"\x1b[0m");
        if *mode == LineNumberMode::Aligned {
            out.push(b'\t');
        }
    }
    out.extend_from_slice(b"\x1b[0m");
    out.extend_from_slice(content.as_bytes());
    out.extend_from_slice(b"\x1b[0m");
    out.push(b'\n');
}

/// Write a non-diff line (passthrough)
fn write_passthrough_line(out: &mut Vec<u8>, content: &str) {
    out.extend_from_slice(b"\x1b[0m");
    out.extend_from_slice(content.as_bytes());
    out.extend_from_slice(b"\x1b[0m");
    out.push(b'\n');
}

/// Parse a hunk header and return (old_start, old_count, new_start, new_count)
fn parse_hunk_header(line: &str) -> Option<(usize, usize, usize, usize)> {
    // @@ -old_start[,old_count] +new_start[,new_count] @@ ...
    let line = line.trim_start_matches("@@ ");
    let rest = line.find(" @@")?;
    let nums = &line[..rest];

    let mut parts = nums.split(' ');
    let old_part = parts.next()?;
    let new_part = parts.next()?;

    let old_part = old_part.trim_start_matches('-');
    let new_part = new_part.trim_start_matches('+');

    let (old_start, old_count) = parse_range(old_part)?;
    let (new_start, new_count) = parse_range(new_part)?;

    Some((old_start, old_count, new_start, new_count))
}

fn parse_range(s: &str) -> Option<(usize, usize)> {
    if let Some(comma) = s.find(',') {
        let start: usize = s[..comma].parse().ok()?;
        let count: usize = s[comma+1..].parse().ok()?;
        Some((start, count))
    } else {
        let start: usize = s.parse().ok()?;
        Some((start, 1))
    }
}

/// Compute line number block string for a given line
/// W = max(digit_count(max_left), digit_count(max_right))
/// Context: right(left, W) + " " + right(right, W)
/// Removed: right(left, W) + " " + " "*W
/// Added: " "*W + " " + right(right, W)
/// When both left==right (context): might show just one number???
///
/// Actually: for context lines, show BOTH numbers even if same
fn format_line_number(
    left: Option<usize>,
    right: Option<usize>,
    w: usize,
    _same_for_context: bool,
) -> String {
    match (left, right) {
        (Some(l), Some(r)) => {
            // Context line: show both
            format!("{:>width$} {:>width$}", l, r, width = w)
        }
        (Some(l), None) => {
            // Removed line: show left, blank right
            format!("{:>width$} {:width$}", l, "", width = w)
        }
        (None, Some(r)) => {
            // Added line: blank left, show right
            format!("{:width$} {:>width$}", "", r, width = w)
        }
        (None, None) => {
            // Shouldn't happen
            format!("{:width$} {:width$}", "", "", width = w)
        }
    }
}

struct HunkState {
    old_line: usize,
    new_line: usize,
    old_count: usize,
    new_count: usize,
    w: usize, // line number display width
    // Collected lines
    removed: Vec<String>,  // content without prefix
    added: Vec<String>,    // content without prefix
}

impl HunkState {
    fn new(old_start: usize, old_count: usize, new_start: usize, new_count: usize) -> Self {
        // Width is based on old_start + old_count and new_start + new_count (not -1)
        let max_old = old_start + old_count;
        let max_new = new_start + new_count;
        let w_old = if max_old == 0 { 1 } else { max_old.to_string().len() };
        let w_new = if max_new == 0 { 1 } else { max_new.to_string().len() };
        let w = w_old.max(w_new);
        HunkState {
            old_line: old_start,
            new_line: new_start,
            old_count,
            new_count,
            w,
            removed: Vec::new(),
            added: Vec::new(),
        }
    }
}

/// Process a batch of removed/added lines and output with diff highlighting
fn process_hunk_batch(
    out: &mut Vec<u8>,
    removed: &[String],
    added: &[String],
    old_line_start: usize,
    new_line_start: usize,
    w: usize,
    faces: &Faces,
    mode: &LineNumberMode,
) {
    let n_rm = removed.len();
    let n_add = added.len();
    let n_pairs = n_rm.min(n_add);

    // Pairing algorithm:
    // First (n_pairs - 1) removed pair with first (n_pairs - 1) added
    // Last removed pairs with last added (if n_pairs > 0)
    // Excess lines from the larger side go in the middle

    // For n_rm > n_add:
    //   First (n_add-1) removed[0..n_add-2] pair with added[0..n_add-2]
    //   removed[n_add-1 .. n_rm-2] are excess (all unique)
    //   Last removed[n_rm-1] pairs with added[n_add-1]
    // For n_add > n_rm:
    //   removed[0..n_rm-2] pair with added[0..n_rm-2]
    //   added[n_rm-1 .. n_add-2] are excess
    //   removed[n_rm-1] pairs with added[n_add-1]
    // For n_rm == n_add:
    //   removed[0..n_rm-2] pair with added[0..n_rm-2]
    //   removed[n_rm-1] pairs with added[n_rm-1]

    // For removed lines: which ones are paired?
    // paired_removed: indices into removed that have a pair
    // paired_added: indices into added that have a pair
    // Their correspondence: paired_removed[i] <-> paired_added[i]

    // Strategy: build the sequence of (rm_idx, add_idx) pairs
    // Then output removed lines in order (some with pair, some as excess)
    // Then output added lines in order (some with pair, some as excess)

    // Build pairs
    let mut pairs: Vec<(usize, usize)> = Vec::new(); // (rm_idx, add_idx)

    if n_pairs > 0 {
        // First n_pairs-1 pairs from top
        for i in 0..n_pairs-1 {
            pairs.push((i, i));
        }
        // Last pair: last of removed with last of added
        pairs.push((n_rm-1, n_add-1));
    }

    // Build per-index data
    // For removed: pair with which added? None if excess
    let mut rm_pair: Vec<Option<usize>> = vec![None; n_rm];
    // For added: pair with which removed? None if excess
    let mut add_pair: Vec<Option<usize>> = vec![None; n_add];

    for (ri, ai) in &pairs {
        rm_pair[*ri] = Some(*ai);
        add_pair[*ai] = Some(*ri);
    }

    // Precompute diffs for paired lines
    let mut diffs: Vec<(Vec<Segment>, Vec<Segment>)> = 
        std::iter::repeat_with(|| (vec![], vec![]))
        .take(n_pairs)
        .collect();

    for (pair_idx, &(ri, ai)) in pairs.iter().enumerate() {
        let (rm_segs, add_segs) = diff_lines(&removed[ri], &added[ai]);
        diffs[pair_idx] = (rm_segs, add_segs);
    }

    // Create a lookup from (ri, ai) pair to diffs
    let mut rm_to_segs: Vec<Option<usize>> = vec![None; n_rm];
    let mut add_to_segs: Vec<Option<usize>> = vec![None; n_add];
    for (pair_idx, &(ri, ai)) in pairs.iter().enumerate() {
        rm_to_segs[ri] = Some(pair_idx);
        add_to_segs[ai] = Some(pair_idx);
    }

    // Output removed lines
    for i in 0..n_rm {
        let old_line_num = old_line_start + i;
        let num_str = if *mode != LineNumberMode::None {
            Some(format_line_number(Some(old_line_num), None, w, false))
        } else {
            None
        };

        if let Some(pair_idx) = rm_to_segs[i] {
            let segs = &diffs[pair_idx].0;
            write_diff_line(
                out, b'-', &removed[i], segs,
                &faces.removed, &faces.refine_removed,
                num_str.as_deref(), mode,
            );
        } else {
            // Excess - all unique
            let all_unique = vec![Segment::UniqueRemoved(removed[i].clone())];
            write_diff_line(
                out, b'-', &removed[i], &all_unique,
                &faces.removed, &faces.refine_removed,
                num_str.as_deref(), mode,
            );
        }
    }

    // Output added lines
    for i in 0..n_add {
        let new_line_num = new_line_start + i;
        let num_str = if *mode != LineNumberMode::None {
            Some(format_line_number(None, Some(new_line_num), w, false))
        } else {
            None
        };

        if let Some(pair_idx) = add_to_segs[i] {
            let segs = &diffs[pair_idx].1;
            write_diff_line(
                out, b'+', &added[i], segs,
                &faces.added, &faces.refine_added,
                num_str.as_deref(), mode,
            );
        } else {
            // Excess - all unique
            let all_unique = vec![Segment::UniqueAdded(added[i].clone())];
            write_diff_line(
                out, b'+', &added[i], &all_unique,
                &faces.added, &faces.refine_added,
                num_str.as_deref(), mode,
            );
        }
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let mut faces = Faces::default();
    let mut mode = LineNumberMode::None;

    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "-h" | "--help" => {
                print_help();
                process::exit(0);
            }
            "-V" | "--version" => {
                println!("diffr {}", VERSION);
                process::exit(0);
            }
            "--colors" => {
                i += 1;
                if i >= args.len() {
                    eprintln!("error: missing argument for --colors");
                    process::exit(255);
                }
                if let Err(e) = parse_color_spec(&args[i], &mut faces) {
                    eprintln!("{}", e);
                    process::exit(255);
                }
            }
            "--line-numbers" => {
                // Check if next arg is "compact" or "aligned"
                if i + 1 < args.len() && (args[i+1] == "compact" || args[i+1] == "aligned") {
                    i += 1;
                    mode = if args[i] == "aligned" {
                        LineNumberMode::Aligned
                    } else {
                        LineNumberMode::Compact
                    };
                } else {
                    mode = LineNumberMode::Compact;
                }
            }
            _ => {
                eprintln!("error: unexpected argument: {}", args[i]);
                process::exit(1);
            }
        }
        i += 1;
    }

    let stdout = io::stdout();
    let mut out_handle = stdout.lock();

    let stdin = io::stdin();
    let mut output = Vec::new();

    // State machine for parsing unified diff
    let mut in_hunk = false;
    let mut hunk: Option<HunkState> = None;
    let mut hunk_old_start = 0usize;
    let mut hunk_new_start = 0usize;

    // Buffer for current batch of removed/added lines
    let mut rm_batch: Vec<String> = Vec::new();
    let mut add_batch: Vec<String> = Vec::new();
    let mut rm_batch_start = 0usize;
    let mut add_batch_start = 0usize;

    for line in stdin.lock().lines() {
        let line = match line {
            Ok(l) => l,
            Err(_) => break,
        };

        let line_bytes = line.as_bytes();

        if in_hunk {
            let h = hunk.as_mut().unwrap();

            if line_bytes.is_empty() || (line_bytes[0] != b' ' && line_bytes[0] != b'-' && line_bytes[0] != b'+' && !line_bytes.starts_with(b"\\")) {
                // End of hunk
                // Flush batch
                if !rm_batch.is_empty() || !add_batch.is_empty() {
                    process_hunk_batch(
                        &mut output, &rm_batch, &add_batch,
                        rm_batch_start, add_batch_start,
                        h.w, &faces, &mode,
                    );
                    rm_batch.clear();
                    add_batch.clear();
                }
                in_hunk = false;
                hunk = None;
                write_passthrough_line(&mut output, &line);
                continue;
            }

            let first = line_bytes[0];

            if line_bytes.starts_with(b"\\") {
                // "\ No newline at end of file" - passthrough
                // First flush any pending batch
                if !rm_batch.is_empty() || !add_batch.is_empty() {
                    process_hunk_batch(
                        &mut output, &rm_batch, &add_batch,
                        rm_batch_start, add_batch_start,
                        h.w, &faces, &mode,
                    );
                    rm_batch.clear();
                    add_batch.clear();
                    rm_batch_start = h.old_line;
                    add_batch_start = h.new_line;
                }
                write_passthrough_line(&mut output, &line);
            } else if first == b' ' {
                // Context line - flush any pending batch first
                if !rm_batch.is_empty() || !add_batch.is_empty() {
                    process_hunk_batch(
                        &mut output, &rm_batch, &add_batch,
                        rm_batch_start, add_batch_start,
                        h.w, &faces, &mode,
                    );
                    rm_batch.clear();
                    add_batch.clear();
                }

                let content = &line[1..]; // strip the space prefix
                let num_str = if mode != LineNumberMode::None {
                    // Context shows both old and new line numbers
                    Some(format_line_number(
                        Some(h.old_line), Some(h.new_line), h.w, true
                    ))
                } else {
                    None
                };
                write_context_line(&mut output, &line, num_str.as_deref(), &mode);
                h.old_line += 1;
                h.new_line += 1;
                rm_batch_start = h.old_line;
                add_batch_start = h.new_line;
            } else if first == b'-' {
                if add_batch.len() > 0 {
                    // We have pending adds but now seeing removes - flush
                    // Actually in proper unified diff, all removes come before adds in a group
                    // But let's be safe
                    process_hunk_batch(
                        &mut output, &rm_batch, &add_batch,
                        rm_batch_start, add_batch_start,
                        h.w, &faces, &mode,
                    );
                    rm_batch.clear();
                    add_batch.clear();
                    rm_batch_start = h.old_line;
                    add_batch_start = h.new_line;
                }
                if rm_batch.is_empty() {
                    rm_batch_start = h.old_line;
                }
                rm_batch.push(line[1..].to_string());
                h.old_line += 1;
            } else if first == b'+' {
                if add_batch.is_empty() {
                    add_batch_start = h.new_line;
                }
                add_batch.push(line[1..].to_string());
                h.new_line += 1;
            }
        } else {
            // Not in hunk
            if line.starts_with("@@ ") {
                if let Some((old_start, old_count, new_start, new_count)) = parse_hunk_header(&line) {
                    let h = HunkState::new(old_start, old_count, new_start, new_count);
                    hunk_old_start = old_start;
                    hunk_new_start = new_start;
                    rm_batch_start = old_start;
                    add_batch_start = new_start;
                    hunk = Some(h);
                    in_hunk = true;
                    rm_batch.clear();
                    add_batch.clear();
                    write_passthrough_line(&mut output, &line);
                    continue;
                }
            }
            write_passthrough_line(&mut output, &line);
        }
    }

    // Flush remaining batch
    if in_hunk {
        if !rm_batch.is_empty() || !add_batch.is_empty() {
            if let Some(h) = &hunk {
                process_hunk_batch(
                    &mut output, &rm_batch, &add_batch,
                    rm_batch_start, add_batch_start,
                    h.w, &faces, &mode,
                );
            }
        }
    }

    out_handle.write_all(&output).unwrap();
}

