                face_name
            ));
        }
    };

    parse_attrs(attrs_str, face)
}

fn parse_attrs(attrs: &str, face: &mut Face) -> Result<(), String> {
    if attrs.is_empty() {
        return Ok(());
    }

    let mut remaining = attrs;

    while !remaining.is_empty() {
        if remaining.starts_with("foreground:") || remaining.starts_with("background:") {
            let is_fg = remaining.starts_with("foreground:");
            let after_type = if is_fg {
                &remaining["foreground:".len()..]
            } else {
                &remaining["background:".len()..]
            };

            let (color_str, rest) = parse_color_value(after_type)?;
            let color = parse_color(&color_str)?;
            if is_fg {
                face.foreground = color;
            } else {
                face.background = color;
            }
            remaining = rest;
        } else {
            let (attr, rest) = if let Some(pos) = remaining.find(':') {
                (&remaining[..pos], &remaining[pos+1..])
            } else {
                (remaining, "")
            };

            match attr {
                "none" => { *face = Face::cleared(); }
                "bold" => { face.bold = Some(true); }
                "nobold" => { face.bold = Some(false); }
                "italic" => { face.italic = Some(true); }
                "noitalic" => { face.italic = Some(false); }
                "underline" => { face.underline = Some(true); }
                "nounderline" => { face.underline = Some(false); }
                "dimmed" => { face.dimmed = Some(true); }
                "nodimmed" => { face.dimmed = Some(false); }
                "intense" => { face.intense = true; }
                "nointense" => { face.intense = false; }
                _ => {
                    return Err(format!(
                        "unexpected attribute name: got '{}', expected foreground|background|italic|noitalic|bold|nobold|dimmed|nodimmed|intense|nointense|underline|nounderline|none",
                        attr
                    ));
                }
            }
            remaining = rest;
        }
    }

    Ok(())
