use std::io::{self, BufRead, Write};
use std::process;

const VERSION: &str = "0.1.5";

#[derive(Debug, Clone)]
struct Face {
    bold: Option<bool>,
    dimmed: Option<bool>,
    italic: Option<bool>,
    underline: Option<bool>,
    intense: bool,
    foreground: ColorSpec,
    background: ColorSpec,
}

#[derive(Debug, Clone, PartialEq)]
enum ColorSpec {
    None,
    Ansi(u8),    // Named ANSI color 0-7
    Ansi256(u8), // 256-color
    Rgb(u8, u8, u8),
}

impl Face {
    fn cleared() -> Self {
        Face {
            bold: None,
            dimmed: None,
            italic: None,
            underline: None,
            intense: false,
            foreground: ColorSpec::None,
            background: ColorSpec::None,
        }
    }

    fn write_ansi(&self, out: &mut Vec<u8>) {
        if self.bold == Some(true) {
            out.extend_from_slice(b"\x1b[1m");
        }
        if self.dimmed == Some(true) {
            out.extend_from_slice(b"\x1b[2m");
        }
        if self.italic == Some(true) {
            out.extend_from_slice(b"\x1b[3m");
        }
        if self.underline == Some(true) {
            out.extend_from_slice(b"\x1b[4m");
        }
        match &self.foreground {
            ColorSpec::None => {}
            ColorSpec::Ansi(c) => {
                if self.intense {
                    let bright = c + 8;
                    write!(out, "\x1b[38;5;{}m", bright).unwrap();
                } else {
                    write!(out, "\x1b[{}m", 30 + c).unwrap();
                }
            }
            ColorSpec::Ansi256(c) => {
                write!(out, "\x1b[38;5;{}m", c).unwrap();
            }
            ColorSpec::Rgb(r, g, b) => {
                write!(out, "\x1b[38;2;{};{};{}m", r, g, b).unwrap();
            }
        }
        match &self.background {
            ColorSpec::None => {}
            ColorSpec::Ansi(c) => {
                if self.intense {
                    let bright = c + 8;
                    write!(out, "\x1b[48;5;{}m", bright).unwrap();
                } else {
                    write!(out, "\x1b[{}m", 40 + c).unwrap();
                }
            }
            ColorSpec::Ansi256(c) => {
                write!(out, "\x1b[48;5;{}m", c).unwrap();
            }
            ColorSpec::Rgb(r, g, b) => {
                write!(out, "\x1b[48;2;{};{};{}m", r, g, b).unwrap();
            }
        }
    }
}

fn default_added() -> Face {
    Face {
        bold: None, dimmed: None, italic: None, underline: None, intense: false,
        foreground: ColorSpec::Ansi(2), background: ColorSpec::None,
    }
}

fn default_removed() -> Face {
    Face {
        bold: None, dimmed: None, italic: None, underline: None, intense: false,
        foreground: ColorSpec::Ansi(1), background: ColorSpec::None,
    }
}

fn default_refine_added() -> Face {
    Face {
        bold: Some(true), dimmed: None, italic: None, underline: None, intense: false,
        foreground: ColorSpec::Rgb(255, 255, 255),
        background: ColorSpec::Ansi(2),
    }
}

fn default_refine_removed() -> Face {
    Face {
        bold: Some(true), dimmed: None, italic: None, underline: None, intense: false,
        foreground: ColorSpec::Rgb(255, 255, 255),
        background: ColorSpec::Ansi(1),
    }
}

fn parse_color_spec(spec: &str, faces: &mut Faces) -> Result<(), String> {
    let mut parts = spec.splitn(2, ':');
    let face_name = parts.next().unwrap_or("");
    let attrs_str = parts.next().unwrap_or("");

    let face = match face_name {
        "added" => &mut faces.added,
        "removed" => &mut faces.removed,
        "refine-added" => &mut faces.refine_added,
        "refine-removed" => &mut faces.refine_removed,
        _ => {
            return Err(format!(
                "unexpected face name: got '{}', expected added|refine-added|removed|refine-removed",
                face_name
            ));
        }
    };

    parse_attrs(attrs_str, face)
}

fn parse_attrs(attrs: &str, face: &mut Face) -> Result<(), String> {
    if attrs.is_empty() {
        return Ok(());
    }

    let mut remaining = attrs;

    while !remaining.is_empty() {
        if remaining.starts_with("foreground:") || remaining.starts_with("background:") {
            let is_fg = remaining.starts_with("foreground:");
            let after_type = if is_fg {
                &remaining["foreground:".len()..]
            } else {
                &remaining["background:".len()..]
            };

            let (color_str, rest) = parse_color_value(after_type)?;
            let color = parse_color(&color_str)?;
            if is_fg {
                face.foreground = color;
            } else {
                face.background = color;
            }
            remaining = rest;
        } else {
            let (attr, rest) = if let Some(pos) = remaining.find(':') {
                (&remaining[..pos], &remaining[pos+1..])
            } else {
                (remaining, "")
            };

            match attr {
                "none" => { *face = Face::cleared(); }
                "bold" => { face.bold = Some(true); }
                "nobold" => { face.bold = Some(false); }
                "italic" => { face.italic = Some(true); }
                "noitalic" => { face.italic = Some(false); }
                "underline" => { face.underline = Some(true); }
                "nounderline" => { face.underline = Some(false); }
                "dimmed" => { face.dimmed = Some(true); }
                "nodimmed" => { face.dimmed = Some(false); }
                "intense" => { face.intense = true; }
                "nointense" => { face.intense = false; }
                _ => {
                    return Err(format!(
                        "unexpected attribute name: got '{}', expected foreground|background|italic|noitalic|bold|nobold|dimmed|nodimmed|intense|nointense|underline|nounderline|none",
                        attr
                    ));
                }
            }
            remaining = rest;
        }
    }

    Ok(())
}

fn parse_color_value(s: &str) -> Result<(String, &str), String> {
    let first_colon = s.find(':');
    let candidate = match first_colon {
        Some(pos) => &s[..pos],
        None => s,
    };

    if candidate.contains(',') {
        let rest = match first_colon {
            Some(pos) => &s[pos+1..],
            None => "",
        };
        return Ok((candidate.to_string(), rest));
    }

    let rest = match first_colon {
        Some(pos) => &s[pos+1..],
        None => "",
    };
    Ok((candidate.to_string(), rest))
}

fn parse_color(s: &str) -> Result<ColorSpec, String> {
    if s == "none" {
        return Ok(ColorSpec::None);
    }

    match s {
        "black" => return Ok(ColorSpec::Ansi(0)),
        "red" => return Ok(ColorSpec::Ansi(1)),
        "green" => return Ok(ColorSpec::Ansi(2)),
        "yellow" => return Ok(ColorSpec::Ansi(3)),
        "blue" => return Ok(ColorSpec::Ansi(4)),
        "magenta" => return Ok(ColorSpec::Ansi(5)),
        "cyan" => return Ok(ColorSpec::Ansi(6)),
        "white" => return Ok(ColorSpec::Ansi(7)),
        _ => {}
    }

    if s.contains(',') {
        let parts: Vec<&str> = s.split(',').collect();
        if parts.len() == 3 {
            let r = parse_u8_or_hex(parts[0])
                .ok_or_else(|| format!("unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{}'", s))?;
            let g = parse_u8_or_hex(parts[1])
                .ok_or_else(|| format!("unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{}'", s))?;
            let b = parse_u8_or_hex(parts[2])
                .ok_or_else(|| format!("unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{}'", s))?;
            return Ok(ColorSpec::Rgb(r, g, b));
        } else {
            return Err(format!("unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{}'", s));
        }
    }

    // Single number (decimal or hex) - 256-color
    if let Some(n) = parse_u8_or_hex_full_check(s) {
        return Ok(ColorSpec::Ansi256(n));
    }

    Err(format!(
        "unexpected color value: unrecognized color name '{}'. Choose from: black, blue, green, red, cyan, magenta, yellow, white",
        s
    ))
}

fn parse_u8_or_hex(s: &str) -> Option<u8> {
    let s = s.trim();
    if s.starts_with("0x") || s.starts_with("0X") {
        u8::from_str_radix(&s[2..], 16).ok()
    } else {
        let n: u16 = s.parse().ok()?;
        if n <= 255 { Some(n as u8) } else { None }
    }
}

fn parse_u8_or_hex_full_check(s: &str) -> Option<u8> {
    let s = s.trim();
    if s.starts_with("0x") || s.starts_with("0X") {
        u8::from_str_radix(&s[2..], 16).ok()
    } else {
        // Check if this is a valid decimal number (digits only)
        if !s.chars().all(|c| c.is_ascii_digit()) {
            return None;
        }
        let n: u64 = s.parse().ok()?;
        if n <= 255 {
            // Generate appropriate error for > 255
            Some(n as u8)
        } else {
            None
        }
    }
}

fn parse_ansi256_check(s: &str) -> Result<ColorSpec, String> {
    let s = s.trim();
    if s.starts_with("0x") || s.starts_with("0X") {
        return u8::from_str_radix(&s[2..], 16)
            .map(ColorSpec::Ansi256)
            .map_err(|_| format!("unexpected color value: unrecognized ansi256 color number, should be '[0-255]' (or a hex number), but is '{}'", s));
    }
    if !s.chars().all(|c| c.is_ascii_digit()) {
        return Err(format!("unexpected color value: unrecognized color name '{}'. Choose from: black, blue, green, red, cyan, magenta, yellow, white", s));
    }
    let n: u64 = s.parse().map_err(|_| format!("unexpected color value: unrecognized ansi256 color number, should be '[0-255]' (or a hex number), but is '{}'", s))?;
    if n <= 255 {
        Ok(ColorSpec::Ansi256(n as u8))
    } else {
        Err(format!("unexpected color value: unrecognized ansi256 color number, should be '[0-255]' (or a hex number), but is '{}'", s))
    }
}

struct Faces {
    added: Face,
    removed: Face,
    refine_added: Face,
    refine_removed: Face,
}

impl Faces {
    fn default() -> Self {
        Faces {
            added: default_added(),
            removed: default_removed(),
            refine_added: default_refine_added(),
            refine_removed: default_refine_removed(),
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
enum LineNumberMode {
    None,
    Compact,
    Aligned,
}

#[derive(Debug, Clone, PartialEq)]
struct Token {
    text: String,
}

fn tokenize(s: &str) -> Vec<Token> {
    let mut tokens = Vec::new();
    if s.is_empty() {
        return tokens;
    }
    let mut current = String::new();
    let mut current_is_ws: Option<bool> = None;

    for c in s.chars() {
        let is_ws = c.is_whitespace();
        match current_is_ws {
            None => {
                current.push(c);
                current_is_ws = Some(is_ws);
            }
            Some(cur_ws) if cur_ws == is_ws => {
                current.push(c);
            }
            Some(_) => {
                tokens.push(Token { text: current.clone() });
                current = c.to_string();
                current_is_ws = Some(is_ws);
            }
        }
    }
    if !current.is_empty() {
        tokens.push(Token { text: current });
    }
    tokens
}

fn compute_lcs_flags(seq1: &[Token], seq2: &[Token]) -> (Vec<bool>, Vec<bool>) {
    let n = seq1.len();
    let m = seq2.len();

    if n == 0 || m == 0 {
        return (vec![false; n], vec![false; m]);
    }

    let mut dp = vec![vec![0u32; m + 1]; n + 1];
    for i in 1..=n {
        for j in 1..=m {
            if seq1[i-1].text == seq2[j-1].text {
                dp[i][j] = dp[i-1][j-1] + 1;
            } else {
                dp[i][j] = dp[i-1][j].max(dp[i][j-1]);
            }
        }
    }

    let mut in_lcs1 = vec![false; n];
    let mut in_lcs2 = vec![false; m];
    let mut i = n;
    let mut j = m;
    while i > 0 && j > 0 {
        if seq1[i-1].text == seq2[j-1].text {
            in_lcs1[i-1] = true;
            in_lcs2[j-1] = true;
            i -= 1;
            j -= 1;
        } else if dp[i-1][j] >= dp[i][j-1] {
            i -= 1;
        } else {
            j -= 1;
        }
    }

    (in_lcs1, in_lcs2)
}

/// A display segment
#[derive(Debug, Clone)]
enum Seg {
    Common(String),
    Unique(String),
}

fn tokens_to_segs(tokens: &[Token], in_lcs: &[bool], is_removed: bool) -> Vec<Seg> {
    let mut segs: Vec<Seg> = Vec::new();
    for (i, tok) in tokens.iter().enumerate() {
        if in_lcs[i] {
            if let Some(Seg::Common(ref mut s)) = segs.last_mut() {
                s.push_str(&tok.text);
            } else {
                segs.push(Seg::Common(tok.text.clone()));
            }
        } else {
            if let Some(Seg::Unique(ref mut s)) = segs.last_mut() {
                s.push_str(&tok.text);
            } else {
                segs.push(Seg::Unique(tok.text.clone()));
            }
        }
    }
    segs
}

fn diff_lines(removed: &str, added: &str) -> (Vec<Seg>, Vec<Seg>) {
    let tokens_rm = tokenize(removed);
    let tokens_add = tokenize(added);

    let (lcs_rm, lcs_add) = compute_lcs_flags(&tokens_rm, &tokens_add);

    let rm_segs = tokens_to_segs(&tokens_rm, &lcs_rm, true);
    let add_segs = tokens_to_segs(&tokens_add, &lcs_add, false);

    (rm_segs, add_segs)
}

/// Write a complete diff line
fn write_diff_line(
    out: &mut Vec<u8>,
    prefix: u8,
    segs: &[Seg],
    face: &Face,
    refine_face: &Face,
    num_str: Option<&str>,
    mode: &LineNumberMode,
) {
    // Line number block (colored with face for removed/added)
    if let Some(ns) = num_str {
        out.extend_from_slice(b"\x1b[0m");
        face.write_ansi(out);
        out.extend_from_slice(ns.as_bytes());
        out.extend_from_slice(b"\x1b[0m");
        if *mode == LineNumberMode::Aligned {
            out.push(b'\t');
        }
    }

    // Prefix character segment
    out.extend_from_slice(b"\x1b[0m");
    face.write_ansi(out);
    out.push(prefix);
    out.extend_from_slice(b"\x1b[0m");

    if segs.is_empty() {
        // Empty content: write ESC[41m (hardcoded)
        out.extend_from_slice(b"\x1b[0m");
        out.extend_from_slice(b"\x1b[41m");
        out.extend_from_slice(b"\x1b[0m");
    } else {
        let last_idx = segs.len() - 1;
        for (i, seg) in segs.iter().enumerate() {
            match seg {
                Seg::Common(s) => {
                    out.extend_from_slice(b"\x1b[0m");
                    face.write_ansi(out);
                    out.extend_from_slice(s.as_bytes());
                    out.extend_from_slice(b"\x1b[0m");
                }
                Seg::Unique(s) => {
                    out.extend_from_slice(b"\x1b[0m");
                    refine_face.write_ansi(out);
                    out.extend_from_slice(s.as_bytes());
                    out.extend_from_slice(b"\x1b[0m");
                }
            }
            if i == last_idx {
                if let Seg::Unique(_) = seg {
                    // Trailing face segment
                    out.extend_from_slice(b"\x1b[0m");
                    face.write_ansi(out);
                    out.extend_from_slice(b"\x1b[0m");
                }
            }
        }
    }

    out.push(b'\n');
}

/// Write a context line
fn write_context_line(
    out: &mut Vec<u8>,
    full_line: &str,  // includes space prefix
    num_str: Option<&str>,
    mode: &LineNumberMode,
) {
    // Context line number block: NO color
    if let Some(ns) = num_str {
        out.extend_from_slice(ns.as_bytes());
        out.extend_from_slice(b"\x1b[0m");
        if *mode == LineNumberMode::Aligned {
            out.push(b'\t');
        }
    }
    // Content (full line including space prefix)
    out.extend_from_slice(b"\x1b[0m");
    out.extend_from_slice(full_line.as_bytes());
    out.extend_from_slice(b"\x1b[0m");
    out.push(b'\n');
}

/// Write a passthrough (non-diff) line
fn write_passthrough_line(out: &mut Vec<u8>, content: &str) {
    out.extend_from_slice(b"\x1b[0m");
    out.extend_from_slice(content.as_bytes());
    out.extend_from_slice(b"\x1b[0m");
    out.push(b'\n');
}

fn parse_hunk_header(line: &str) -> Option<(usize, usize, usize, usize)> {
    // @@ -old_start[,old_count] +new_start[,new_count] @@
    if !line.starts_with("@@ ") {
        return None;
    }
    let after = &line[3..]; // skip "@@ "
    let end = after.find(" @@")?;
    let nums = &after[..end];

    let mut parts = nums.split_whitespace();
    let old_part = parts.next()?;
    let new_part = parts.next()?;

    let old_str = old_part.trim_start_matches('-');
    let new_str = new_part.trim_start_matches('+');

    let (old_start, old_count) = parse_range(old_str)?;
    let (new_start, new_count) = parse_range(new_str)?;

    Some((old_start, old_count, new_start, new_count))
}

fn parse_range(s: &str) -> Option<(usize, usize)> {
    if let Some(comma) = s.find(',') {
        let start: usize = s[..comma].parse().ok()?;
        let count: usize = s[comma+1..].parse().ok()?;
        Some((start, count))
    } else {
        let start: usize = s.parse().ok()?;
        Some((start, 1))
    }
}

/// Compute the line number display width W
/// W = max(digits(old_start + old_count), digits(new_start + new_count))
fn compute_w(old_start: usize, old_count: usize, new_start: usize, new_count: usize) -> usize {
    let max_old = old_start + old_count;
    let max_new = new_start + new_count;
    let w_old = num_digits(max_old);
    let w_new = num_digits(max_new);
    w_old.max(w_new)
}

fn num_digits(n: usize) -> usize {
    if n == 0 { 1 } else { n.to_string().len() }
}

/// Format line number block for context, removed, or added lines
/// Context: if left==right: right-align(right, 2*W+1) [just one number]
///          else: right(left, W) + " " + right(right, W)
/// Removed: right(left, W) + " " + " "*W
/// Added: " "*W + " " + right(right, W)
fn fmt_linenum_context(left: usize, right: usize, w: usize) -> String {
    if left == right {
        // Show just the right number, right-aligned to 2*W+1 total
        format!("{:>width$}", right, width = 2*w+1)
    } else {
        format!("{:>width$} {:>width$}", left, right, width = w)
    }
}

fn fmt_linenum_removed(left: usize, w: usize) -> String {
    format!("{:>width$} {:width$}", left, "", width = w)
}

fn fmt_linenum_added(right: usize, w: usize) -> String {
    format!("{:width$} {:>width$}", "", right, width = w)
}

/// Process a batch of removed/added lines
fn process_batch(
    out: &mut Vec<u8>,
    removed: &[String],
    added: &[String],
    old_start: usize,  // 0-indexed start within the file
    new_start: usize,
    w: usize,
    faces: &Faces,
    mode: &LineNumberMode,
) {
    let n_rm = removed.len();
    let n_add = added.len();
    let n_pairs = n_rm.min(n_add);

    // Pairing: first (n_pairs-1) removed line with first (n_pairs-1) added lines
    // Last removed line (if any pair) with last added line

    // Compute diffs for each pair
    let mut pair_diffs: Vec<(Vec<Seg>, Vec<Seg>)> = Vec::with_capacity(n_pairs);

    if n_pairs > 0 {
        // First n_pairs-1 pairs
        for i in 0..n_pairs-1 {
            pair_diffs.push(diff_lines(&removed[i], &added[i]));
        }
        // Last pair
        pair_diffs.push(diff_lines(&removed[n_rm-1], &added[n_add-1]));
    }

    // Output removed lines
    for i in 0..n_rm {
        let line_num = old_start + i;
        let num_str = if *mode != LineNumberMode::None {
            Some(fmt_linenum_removed(line_num + 1, w))
        } else {
            None
        };

        let segs = if n_pairs > 0 {
            if i < n_pairs - 1 {
                // Paired from top
                &pair_diffs[i].0
            } else if i == n_rm - 1 {
                // Last pair (from bottom)
                &pair_diffs[n_pairs-1].0
            } else {
                // Excess - all unique
                &pair_diffs[0].0 // placeholder, won't be used
            }
        } else {
            &pair_diffs[0].0 // placeholder
        };

        // Check if this is an excess (unpaired) line
        let is_excess = if n_pairs == 0 {
            true
        } else if i < n_pairs - 1 {
            false // paired from top
        } else if i == n_rm - 1 {
            false // last pair
        } else {
            true // middle excess
        };

        if is_excess {
            let all_unique = vec![Seg::Unique(removed[i].clone())];
            write_diff_line(out, b'-', &all_unique, &faces.removed, &faces.refine_removed,
                            num_str.as_deref(), mode);
        } else {
            write_diff_line(out, b'-', segs, &faces.removed, &faces.refine_removed,
                            num_str.as_deref(), mode);
        }
    }

    // Output added lines
    for i in 0..n_add {
        let line_num = new_start + i;
        let num_str = if *mode != LineNumberMode::None {
            Some(fmt_linenum_added(line_num + 1, w))
        } else {
            None
        };

        let is_excess = if n_pairs == 0 {
            true
        } else if i < n_pairs - 1 {
            false // paired from top
        } else if i == n_add - 1 {
            false // last pair
        } else {
            true // middle excess
        };

        if is_excess {
            let all_unique = vec![Seg::Unique(added[i].clone())];
            write_diff_line(out, b'+', &all_unique, &faces.added, &faces.refine_added,
                            num_str.as_deref(), mode);
        } else {
            // Determine which pair index
            let pair_idx = if i < n_pairs - 1 {
                i // paired from top
            } else {
                n_pairs - 1 // last pair
            };
            let segs = &pair_diffs[pair_idx].1;
            write_diff_line(out, b'+', segs, &faces.added, &faces.refine_added,
                            num_str.as_deref(), mode);
        }
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let mut faces = Faces::default();
    let mut mode = LineNumberMode::None;

    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "-h" | "--help" => {
                print_help();
                process::exit(0);
            }
            "-V" | "--version" => {
                println!("diffr {}", VERSION);
                process::exit(0);
            }
            "--colors" => {
                i += 1;
                if i >= args.len() {
                    eprintln!("error: missing argument for --colors");
                    process::exit(255);
                }
                if let Err(e) = parse_color_spec(&args[i], &mut faces) {
                    eprintln!("{}", e);
                    process::exit(255);
                }
            }
            "--line-numbers" => {
                if i + 1 < args.len() && (args[i+1] == "compact" || args[i+1] == "aligned") {
                    i += 1;
                    mode = if args[i] == "aligned" {
                        LineNumberMode::Aligned
                    } else {
                        LineNumberMode::Compact
                    };
                } else {
                    mode = LineNumberMode::Compact;
                }
            }
            _ => {
                eprintln!("error: unexpected argument: {}", args[i]);
                process::exit(1);
            }
        }
        i += 1;
    }

    let stdout = io::stdout();
    let mut out_handle = stdout.lock();
    let mut output: Vec<u8> = Vec::new();

    let stdin = io::stdin();

    // Parser state
    let mut in_hunk = false;
    let mut w = 1usize;
    let mut old_line = 0usize; // 0-indexed
    let mut new_line = 0usize;

    // Current batch
    let mut rm_batch: Vec<String> = Vec::new();
    let mut add_batch: Vec<String> = Vec::new();
    let mut rm_batch_start = 0usize; // 0-indexed
    let mut add_batch_start = 0usize;

    let flush_batch = |output: &mut Vec<u8>, rm: &mut Vec<String>, add: &mut Vec<String>,
                       rms: usize, ads: usize, w: usize, faces: &Faces, mode: &LineNumberMode| {
        if !rm.is_empty() || !add.is_empty() {
            process_batch(output, rm, add, rms, ads, w, faces, mode);
            rm.clear();
            add.clear();
        }
    };

    for line in stdin.lock().lines() {
        let line = match line {
            Ok(l) => l,
            Err(_) => break,
        };

        if in_hunk {
            let first = line.as_bytes().first().copied();

            match first {
                Some(b' ') => {
                    // Context line
                    flush_batch(&mut output, &mut rm_batch, &mut add_batch,
                                rm_batch_start, add_batch_start, w, &faces, &mode);
                    rm_batch_start = old_line + 1;
                    add_batch_start = new_line + 1;

                    let num_str = if mode != LineNumberMode::None {
                        Some(fmt_linenum_context(old_line + 1, new_line + 1, w))
                    } else {
                        None
                    };
                    write_context_line(&mut output, &line, num_str.as_deref(), &mode);
                    old_line += 1;
                    new_line += 1;
                }
                Some(b'-') => {
                    if !add_batch.is_empty() {
                        // Shouldn't happen in normal diffs but handle it
                        flush_batch(&mut output, &mut rm_batch, &mut add_batch,
                                    rm_batch_start, add_batch_start, w, &faces, &mode);
                        rm_batch_start = old_line;
                        add_batch_start = new_line;
                    }
                    if rm_batch.is_empty() {
                        rm_batch_start = old_line;
                    }
                    rm_batch.push(line[1..].to_string());
                    old_line += 1;
                }
                Some(b'+') => {
                    if add_batch.is_empty() {
                        add_batch_start = new_line;
                    }
                    add_batch.push(line[1..].to_string());
                    new_line += 1;
                }
                Some(b'\\') => {
                    // "\ No newline at end of file" - flush and passthrough
                    flush_batch(&mut output, &mut rm_batch, &mut add_batch,
                                rm_batch_start, add_batch_start, w, &faces, &mode);
                    rm_batch_start = old_line;
                    add_batch_start = new_line;
                    write_passthrough_line(&mut output, &line);
                }
                _ => {
                    // End of hunk
                    flush_batch(&mut output, &mut rm_batch, &mut add_batch,
                                rm_batch_start, add_batch_start, w, &faces, &mode);
                    in_hunk = false;

                    // Check if this is a new hunk header
                    if line.starts_with("@@ ") {
                        if let Some((os, oc, ns, nc)) = parse_hunk_header(&line) {
                            w = compute_w(os, oc, ns, nc);
                            old_line = os - 1; // 0-indexed start (will be used as os-1+1=os for first line)
                            new_line = ns - 1;
                            // Actually: old_line should be os (1-based)
                            // Let me use 0-indexed where old_line = start - 1
                            old_line = os.saturating_sub(1);
                            new_line = ns.saturating_sub(1);
                            rm_batch_start = old_line;
                            add_batch_start = new_line;
                            rm_batch.clear();
                            add_batch.clear();
                            in_hunk = true;
                            write_passthrough_line(&mut output, &line);
                            continue;
                        }
                    }
                    write_passthrough_line(&mut output, &line);
                }
            }
        } else {
            if line.starts_with("@@ ") {
                if let Some((os, oc, ns, nc)) = parse_hunk_header(&line) {
                    w = compute_w(os, oc, ns, nc);
                    old_line = os.saturating_sub(1);
                    new_line = ns.saturating_sub(1);
                    rm_batch_start = old_line;
                    add_batch_start = new_line;
                    rm_batch.clear();
                    add_batch.clear();
                    in_hunk = true;
                    write_passthrough_line(&mut output, &line);
                    continue;
                }
            }
            write_passthrough_line(&mut output, &line);
        }
    }

    // Flush remaining
    if in_hunk && (!rm_batch.is_empty() || !add_batch.is_empty()) {
        process_batch(&mut output, &rm_batch, &add_batch,
                      rm_batch_start, add_batch_start, w, &faces, &mode);
    }

    out_handle.write_all(&output).unwrap();
}

fn print_help() {
    let help = concat!(
        "diffr $VERSION\n",
        "Nathan Moreau <nathan.moreau@m4x.org>\n",
        "\n",
        "diffr adds word-level diff on top of unified diffs.\n",
        "word-level diff information is displayed using text attributes.\n",
        "\n",
        "USAGE:\n",
        "    diffr reads from standard input and writes to standard output.\n",
        "\n",
        "    Typical usage is for interactive use of diff:\n",
        "    diff -u <file1> <file2> | diffr\n",
        "    git show | diffr\n",
        "\n",
        "OPTIONS:\n",
        "        --colors <COLOR_SPEC>...\n",
        "            Configure color settings for console ouput.\n",
        "\n",
        "            There are four faces to customize:\n",
        "            +----------------+--------------+----------------+\n",
        "            |  line prefix   |      +       |       -        |\n",
        "            +----------------+--------------+----------------+\n",
        "            | common segment |    added     |    removed     |\n",
        "            | unique segment | refine-added | refine-removed |\n",
        "            +----------------+--------------+----------------+\n",
        "\n",
        "            The customization allows\n",
        "            - to change the foreground or background color;\n",
        "            - to set or unset the attributes 'bold', 'intense', 'underline';\n",
        "            - to clear all attributes.\n",
        "\n",
        "            Customization is done passing a color_spec argument.\n",
        "            This flag may be provided multiple times.\n",
        "\n",
        "            The syntax is the following:\n",
        "\n",
        "            color_spec = face-name + ':' + attributes\n",
        "            attributes = attribute\n",
        "                       | attribute + ':' + attributes\n",
        "            attribute  = ('foreground' | 'background') + ':' + color\n",
        "                       | (<empty> | 'no') + font-flag\n",
        "                       | 'none'\n",
        "            font-flag  = 'italic'\n",
        "                       | 'bold'\n",
        "                       | 'intense'\n",
        "                       | 'underline'\n",
        "            color      = 'none'\n",
        "                       | [0-255]\n",
        "                       | [0-255] + ',' + [0-255] + ',' + [0-255]\n",
        "                       | ('black', 'blue', 'green', 'red',\n",
        "                          'cyan', 'magenta', 'yellow', 'white')\n",
        "\n",
        "            For example, the color_spec\n",
        "\n",
        "                'refine-added:background:blue:bold'\n",
        "\n",
        "            sets the color of unique added segments with\n",
        "            a blue background, written with a bold font.\n",
        "\n",
        "        --line-numbers <compact|aligned>\n",
        "            Display line numbers. Style is optional.\n",
        "            When style = 'compact', take as little width as possible.\n",
        "            When style = 'aligned', align to tab stops (useful if tab is used for indentation). [default: compact]\n",
        "\n",
        "    -h, --help\n",
        "            Prints help information\n",
        "\n",
        "    -V, --version\n",
        "            Prints version information",
    );
    // Replace $VERSION
    let help = help.replace("$VERSION", VERSION);
    println!("{}", help);
}
