use std::io::{self, BufRead, Write};
use std::process;

const VERSION: &str = "0.1.5";

#[derive(Debug, Clone)]
struct Face {
    bold: Option<bool>,
    dimmed: Option<bool>,
    italic: Option<bool>,
    underline: Option<bool>,
    intense: bool,
    foreground: ColorSpec,
    background: ColorSpec,
}

#[derive(Debug, Clone, PartialEq)]
enum ColorSpec {
    None,
    Ansi(u8),
    Ansi256(u8),
    Rgb(u8, u8, u8),
}

impl Face {
    fn cleared() -> Self {
        Face {
            bold: None, dimmed: None, italic: None, underline: None, intense: false,
            foreground: ColorSpec::None, background: ColorSpec::None,
        }
    }

    fn write_ansi(&self, out: &mut Vec<u8>) {
        if self.bold == Some(true) { out.extend_from_slice(b"\x1b[1m"); }
        if self.dimmed == Some(true) { out.extend_from_slice(b"\x1b[2m"); }
        if self.italic == Some(true) { out.extend_from_slice(b"\x1b[3m"); }
        if self.underline == Some(true) { out.extend_from_slice(b"\x1b[4m"); }
        match &self.foreground {
            ColorSpec::None => {}
            ColorSpec::Ansi(c) => {
                if self.intense { write!(out, "\x1b[38;5;{}m", c + 8).unwrap(); }
                else { write!(out, "\x1b[{}m", 30 + c).unwrap(); }
            }
            ColorSpec::Ansi256(c) => { write!(out, "\x1b[38;5;{}m", c).unwrap(); }
            ColorSpec::Rgb(r, g, b) => { write!(out, "\x1b[38;2;{};{};{}m", r, g, b).unwrap(); }
        }
        match &self.background {
            ColorSpec::None => {}
            ColorSpec::Ansi(c) => {
                if self.intense { write!(out, "\x1b[48;5;{}m", c + 8).unwrap(); }
                else { write!(out, "\x1b[{}m", 40 + c).unwrap(); }
            }
            ColorSpec::Ansi256(c) => { write!(out, "\x1b[48;5;{}m", c).unwrap(); }
            ColorSpec::Rgb(r, g, b) => { write!(out, "\x1b[48;2;{};{};{}m", r, g, b).unwrap(); }
        }
    }
}

fn default_added() -> Face {
    Face { bold: None, dimmed: None, italic: None, underline: None, intense: false,
           foreground: ColorSpec::Ansi(2), background: ColorSpec::None }
}
fn default_removed() -> Face {
    Face { bold: None, dimmed: None, italic: None, underline: None, intense: false,
           foreground: ColorSpec::Ansi(1), background: ColorSpec::None }
}
fn default_refine_added() -> Face {
    Face { bold: Some(true), dimmed: None, italic: None, underline: None, intense: false,
           foreground: ColorSpec::Rgb(255, 255, 255), background: ColorSpec::Ansi(2) }
}
fn default_refine_removed() -> Face {
    Face { bold: Some(true), dimmed: None, italic: None, underline: None, intense: false,
           foreground: ColorSpec::Rgb(255, 255, 255), background: ColorSpec::Ansi(1) }
}

fn parse_color_spec(spec: &str, faces: &mut Faces) -> Result<(), String> {
    let mut parts = spec.splitn(2, ':');
    let face_name = parts.next().unwrap_or("");
    let attrs_str = parts.next().unwrap_or("");
    let face = match face_name {
        "added" => &mut faces.added,
        "removed" => &mut faces.removed,
        "refine-added" => &mut faces.refine_added,
        "refine-removed" => &mut faces.refine_removed,
        _ => return Err(format!(
            "unexpected face name: got '{}', expected added|refine-added|removed|refine-removed",
            face_name
        )),
    };
    parse_attrs(attrs_str, face)
}

fn parse_attrs(attrs: &str, face: &mut Face) -> Result<(), String> {
    if attrs.is_empty() { return Ok(()); }
    let mut remaining = attrs;
    while !remaining.is_empty() {
        if remaining.starts_with("foreground:") || remaining.starts_with("background:") {
            let is_fg = remaining.starts_with("foreground:");
            let after_type = if is_fg { &remaining["foreground:".len()..] }
                             else { &remaining["background:".len()..] };
            let (color_str, rest) = parse_color_value(after_type)?;
            let color = parse_color(&color_str)?;
            if is_fg { face.foreground = color; } else { face.background = color; }
            remaining = rest;
        } else {
            let (attr, rest) = if let Some(pos) = remaining.find(':') {
                (&remaining[..pos], &remaining[pos+1..])
            } else { (remaining, "") };
            match attr {
                "none" => { *face = Face::cleared(); }
                "bold" => { face.bold = Some(true); }
                "nobold" => { face.bold = Some(false); }
                "italic" => { face.italic = Some(true); }
                "noitalic" => { face.italic = Some(false); }
                "underline" => { face.underline = Some(true); }
                "nounderline" => { face.underline = Some(false); }
                "dimmed" => { face.dimmed = Some(true); }
                "nodimmed" => { face.dimmed = Some(false); }
                "intense" => { face.intense = true; }
                "nointense" => { face.intense = false; }
                _ => return Err(format!(
                    "unexpected attribute name: got '{}', expected foreground|background|italic|noitalic|bold|nobold|dimmed|nodimmed|intense|nointense|underline|nounderline|none",
                    attr
                )),
            }
            remaining = rest;
        }
    }
    Ok(())
}

fn parse_color_value(s: &str) -> Result<(String, &str), String> {
    let first_colon = s.find(':');
    let candidate = match first_colon { Some(pos) => &s[..pos], None => s };
    if candidate.contains(',') {
        let rest = match first_colon { Some(pos) => &s[pos+1..], None => "" };
        return Ok((candidate.to_string(), rest));
    }
    let rest = match first_colon { Some(pos) => &s[pos+1..], None => "" };
    Ok((candidate.to_string(), rest))
}

fn parse_color(s: &str) -> Result<ColorSpec, String> {
    if s == "none" { return Ok(ColorSpec::None); }
    match s {
        "black" => return Ok(ColorSpec::Ansi(0)),
        "red" => return Ok(ColorSpec::Ansi(1)),
        "green" => return Ok(ColorSpec::Ansi(2)),
        "yellow" => return Ok(ColorSpec::Ansi(3)),
        "blue" => return Ok(ColorSpec::Ansi(4)),
        "magenta" => return Ok(ColorSpec::Ansi(5)),
        "cyan" => return Ok(ColorSpec::Ansi(6)),
        "white" => return Ok(ColorSpec::Ansi(7)),
        _ => {}
    }
    if s.contains(',') {
        let parts: Vec<&str> = s.split(',').collect();
        if parts.len() != 3 {
            return Err(format!("unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{}'", s));
        }
        let r = parse_u8_hex(parts[0]).ok_or_else(|| format!("unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{}'", s))?;
        let g = parse_u8_hex(parts[1]).ok_or_else(|| format!("unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{}'", s))?;
        let b = parse_u8_hex(parts[2]).ok_or_else(|| format!("unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{}'", s))?;
        return Ok(ColorSpec::Rgb(r, g, b));
    }
    // Single number or hex
    let s_trim = s.trim();
    let is_numeric = s_trim.starts_with("0x") || s_trim.starts_with("0X") ||
                     s_trim.chars().all(|c| c.is_ascii_digit());
    if is_numeric {
        return parse_ansi256(s);
    }
    Err(format!(
        "unexpected color value: unrecognized color name '{}'. Choose from: black, blue, green, red, cyan, magenta, yellow, white",
        s
    ))
}

fn parse_u8_hex(s: &str) -> Option<u8> {
    let s = s.trim();
    if s.starts_with("0x") || s.starts_with("0X") {
        u8::from_str_radix(&s[2..], 16).ok()
    } else {
        let n: u16 = s.parse().ok()?;
        if n <= 255 { Some(n as u8) } else { None }
    }
}

fn parse_ansi256(s: &str) -> Result<ColorSpec, String> {
    let s = s.trim();
    if s.starts_with("0x") || s.starts_with("0X") {
        return u8::from_str_radix(&s[2..], 16)
            .map(ColorSpec::Ansi256)
            .map_err(|_| format!("unexpected color value: unrecognized ansi256 color number, should be '[0-255]' (or a hex number), but is '{}'", s));
    }
    if !s.chars().all(|c| c.is_ascii_digit()) {
        return Err(format!("unexpected color value: unrecognized color name '{}'. Choose from: black, blue, green, red, cyan, magenta, yellow, white", s));
    }
    let n: u64 = s.parse().map_err(|_| format!("unexpected color value: unrecognized ansi256 color number, should be '[0-255]' (or a hex number), but is '{}'", s))?;
    if n <= 255 { Ok(ColorSpec::Ansi256(n as u8)) }
    else { Err(format!("unexpected color value: unrecognized ansi256 color number, should be '[0-255]' (or a hex number), but is '{}'", s)) }
}

struct Faces {
    added: Face,
    removed: Face,
    refine_added: Face,
    refine_removed: Face,
}
impl Faces {
    fn default() -> Self {
        Faces { added: default_added(), removed: default_removed(),
                refine_added: default_refine_added(), refine_removed: default_refine_removed() }
    }
}

#[derive(Debug, Clone, PartialEq)]
enum LineNumberMode { None, Compact, Aligned }

#[derive(Debug, Clone, PartialEq)]
struct Token { text: String }

fn tokenize(s: &str) -> Vec<Token> {
    if s.is_empty() { return vec![]; }
    let mut tokens = Vec::new();
    let mut current = String::new();
    let mut current_is_ws: Option<bool> = None;
    for c in s.chars() {
        let is_ws = c.is_whitespace();
        match current_is_ws {
            None => { current.push(c); current_is_ws = Some(is_ws); }
            Some(cw) if cw == is_ws => { current.push(c); }
            Some(_) => {
                tokens.push(Token { text: current.clone() });
                current = c.to_string();
                current_is_ws = Some(is_ws);
            }
        }
    }
    if !current.is_empty() { tokens.push(Token { text: current }); }
    tokens
}

fn compute_lcs(seq1: &[Token], seq2: &[Token]) -> (Vec<bool>, Vec<bool>) {
    let (n, m) = (seq1.len(), seq2.len());
    if n == 0 || m == 0 { return (vec![false; n], vec![false; m]); }
    let mut dp = vec![vec![0u32; m + 1]; n + 1];
    for i in 1..=n {
        for j in 1..=m {
            dp[i][j] = if seq1[i-1].text == seq2[j-1].text {
                dp[i-1][j-1] + 1
            } else {
                dp[i-1][j].max(dp[i][j-1])
            };
        }
    }
    let mut in1 = vec![false; n];
    let mut in2 = vec![false; m];
    let (mut i, mut j) = (n, m);
    while i > 0 && j > 0 {
        if seq1[i-1].text == seq2[j-1].text {
            in1[i-1] = true; in2[j-1] = true; i -= 1; j -= 1;
        } else if dp[i-1][j] >= dp[i][j-1] { i -= 1; } else { j -= 1; }
    }
    (in1, in2)
}

#[derive(Debug, Clone)]
enum Seg { Common(String), Unique(String) }

fn build_segs(tokens: &[Token], in_lcs: &[bool]) -> Vec<Seg> {
    let mut segs: Vec<Seg> = Vec::new();
    for (i, tok) in tokens.iter().enumerate() {
        if in_lcs[i] {
            if let Some(Seg::Common(ref mut s)) = segs.last_mut() { s.push_str(&tok.text); }
            else { segs.push(Seg::Common(tok.text.clone())); }
        } else {
            if let Some(Seg::Unique(ref mut s)) = segs.last_mut() { s.push_str(&tok.text); }
            else { segs.push(Seg::Unique(tok.text.clone())); }
        }
    }
    segs
}

fn diff_lines(removed: &str, added: &str) -> (Vec<Seg>, Vec<Seg>) {
    let t1 = tokenize(removed);
    let t2 = tokenize(added);
    let (in1, in2) = compute_lcs(&t1, &t2);
    (build_segs(&t1, &in1), build_segs(&t2, &in2))
}

fn write_segs(
    out: &mut Vec<u8>,
    prefix: u8,
    segs: &[Seg],
    face: &Face,
    refine_face: &Face,
    num_str: Option<&str>,
    mode: &LineNumberMode,
    is_excess: bool,
) {
    // Line number block
    if let Some(ns) = num_str {
        out.extend_from_slice(b"\x1b[0m");
        face.write_ansi(out);
        out.extend_from_slice(ns.as_bytes());
        out.extend_from_slice(b"\x1b[0m");
        if *mode == LineNumberMode::Aligned { out.push(b'\t'); }
    }

    if segs.is_empty() {
        // Empty line content
        out.extend_from_slice(b"\x1b[0m");
        face.write_ansi(out);
        out.push(prefix);
        out.extend_from_slice(b"\x1b[0m");
        out.extend_from_slice(b"\x1b[0m\x1b[41m\x1b[0m");
    } else {
        // Check if first seg is Common with leading whitespace to merge with prefix
        let leading_ws = if let Seg::Common(s) = &segs[0] {
            let ws_end = s.find(|c: char| !c.is_whitespace()).unwrap_or(s.len());
            if ws_end > 0 { Some(ws_end) } else { None }
        } else { None };

        // Determine the "effective" first segment content
        let (prefix_extra, seg_start_offset): (&str, usize) = if let Some(ws_end) = leading_ws {
            if let Seg::Common(s) = &segs[0] { (&s[..ws_end], ws_end) } else { ("", 0) }
        } else { ("", 0) };

        // Write first segment (prefix + possible leading ws)
        out.extend_from_slice(b"\x1b[0m");
        face.write_ansi(out);
        out.push(prefix);
        out.extend_from_slice(prefix_extra.as_bytes());
        out.extend_from_slice(b"\x1b[0m");

        // Build effective segments list
        let mut effective: Vec<Seg> = Vec::new();
        if let Seg::Common(s) = &segs[0] {
            if seg_start_offset < s.len() {
                effective.push(Seg::Common(s[seg_start_offset..].to_string()));
            }
        } else {
            effective.push(segs[0].clone());
        }
        for s in segs[1..].iter() { effective.push(s.clone()); }

        let last_idx = effective.len().saturating_sub(1);
        for (i, seg) in effective.iter().enumerate() {
            match seg {
                Seg::Common(s) => {
                    out.extend_from_slice(b"\x1b[0m");
                    face.write_ansi(out);
                    out.extend_from_slice(s.as_bytes());
                    out.extend_from_slice(b"\x1b[0m");
                }
                Seg::Unique(s) => {
                    out.extend_from_slice(b"\x1b[0m");
                    refine_face.write_ansi(out);
                    out.extend_from_slice(s.as_bytes());
                    out.extend_from_slice(b"\x1b[0m");
                }
            }
            if !effective.is_empty() && i == last_idx && !is_excess {
                if let Seg::Unique(_) = seg {
                    out.extend_from_slice(b"\x1b[0m");
                    face.write_ansi(out);
                    out.extend_from_slice(b"\x1b[0m");
                }
            }
        }
    }
    out.push(b'\n');
}

fn write_context(out: &mut Vec<u8>, full_line: &str, num_str: Option<&str>, mode: &LineNumberMode) {
    if let Some(ns) = num_str {
        out.extend_from_slice(ns.as_bytes());
        if *mode == LineNumberMode::Aligned {
            out.push(b'\t');
            out.extend_from_slice(b"\x1b[0m");
        } else {
            out.extend_from_slice(b"\x1b[0m");
        }
    } else {
        out.extend_from_slice(b"\x1b[0m");
    }
    out.extend_from_slice(full_line.as_bytes());
    out.extend_from_slice(b"\x1b[0m");
    out.push(b'\n');
}

fn write_passthrough(out: &mut Vec<u8>, line: &str) {
    out.extend_from_slice(b"\x1b[0m");
    out.extend_from_slice(line.as_bytes());
    out.extend_from_slice(b"\x1b[0m");
    out.push(b'\n');
}

fn num_digits(n: usize) -> usize {
    if n == 0 { 1 } else { n.to_string().len() }
}

fn compute_w(os: usize, oc: usize, ns: usize, nc: usize) -> usize {
    num_digits(os + oc).max(num_digits(ns + nc))
}

fn fmt_ctx(left: usize, right: usize, w: usize) -> String {
    if left == right {
        format!("{:>width$}", right, width = 2*w+1)
    } else {
        format!("{:>width$} {:>width$}", left, right, width = w)
    }
}

fn fmt_rm(left: usize, w: usize) -> String {
    format!("{:>width$} {:width$}", left, "", width = w)
}

fn fmt_add(right: usize, w: usize) -> String {
    format!("{:width$} {:>width$}", "", right, width = w)
}

fn parse_hunk(line: &str) -> Option<(usize, usize, usize, usize)> {
    if !line.starts_with("@@ ") { return None; }
    let after = &line[3..];
    let end = after.find(" @@")?;
    let nums = &after[..end];
    let mut parts = nums.split_whitespace();
    let op = parts.next()?.trim_start_matches('-');
    let np = parts.next()?.trim_start_matches('+');
    let (os, oc) = parse_range(op)?;
    let (ns, nc) = parse_range(np)?;
    Some((os, oc, ns, nc))
}

fn parse_range(s: &str) -> Option<(usize, usize)> {
    if let Some(c) = s.find(',') {
        Some((s[..c].parse().ok()?, s[c+1..].parse().ok()?))
    } else {
        Some((s.parse().ok()?, 1))
    }
}

/// Events in a hunk batch
#[derive(Debug)]
enum HunkEvent {
    Remove { content: String, line_num: usize },  // 0-indexed line number in old file
    Add { content: String, line_num: usize },       // 0-indexed in new file
    Passthrough { line: String },
}

/// Flush a hunk batch - output events in order with proper styling
fn flush_batch(
    out: &mut Vec<u8>,
    events: &[HunkEvent],
    w: usize,
    faces: &Faces,
    mode: &LineNumberMode,
) {
    if events.is_empty() { return; }

    // Collect removes and adds
    let removes: Vec<(usize, &str)> = events.iter().filter_map(|e| {
        if let HunkEvent::Remove { content, line_num } = e { Some((*line_num, content.as_str())) }
        else { None }
    }).collect();

    let adds: Vec<(usize, &str)> = events.iter().filter_map(|e| {
        if let HunkEvent::Add { content, line_num } = e { Some((*line_num, content.as_str())) }
        else { None }
    }).collect();

    let n_rm = removes.len();
    let n_add = adds.len();
    let n_pairs = n_rm.min(n_add);

    // Compute diffs for paired lines
    let mut pair_diffs: Vec<(Vec<Seg>, Vec<Seg>)> = Vec::with_capacity(n_pairs);
    if n_pairs > 0 {
        for i in 0..n_pairs-1 {
            pair_diffs.push(diff_lines(removes[i].1, adds[i].1));
        }
        pair_diffs.push(diff_lines(removes[n_rm-1].1, adds[n_add-1].1));
    }

    // Determine which remove/add indices are paired
    let rm_pair: Vec<Option<usize>> = (0..n_rm).map(|i| {
        if n_pairs == 0 { None }
        else if i < n_pairs - 1 { Some(i) }
        else if i == n_rm - 1 { Some(n_pairs - 1) }
        else { None }
    }).collect();

    let add_pair: Vec<Option<usize>> = (0..n_add).map(|i| {
        if n_pairs == 0 { None }
        else if i < n_pairs - 1 { Some(i) }
        else if i == n_add - 1 { Some(n_pairs - 1) }
        else { None }
    }).collect();

    // Output events in order
    let mut rm_idx = 0usize;
    let mut add_idx = 0usize;

    for event in events {
        match event {
            HunkEvent::Remove { content, line_num } => {
                let i = rm_idx;
                rm_idx += 1;
                let num_str = if *mode != LineNumberMode::None {
                    Some(fmt_rm(line_num + 1, w))
                } else { None };
                let (segs, is_excess) = if let Some(pidx) = rm_pair[i] {
                    (&pair_diffs[pidx].0 as &Vec<Seg>, false)
                } else {
                    // excess - need to create all-unique segs
                    // We'll handle this separately
                    (&pair_diffs[0].0 as &Vec<Seg>, true) // placeholder
                };
                if is_excess {
                    let eu = vec![Seg::Unique(content.clone())];
                    write_segs(out, b'-', &eu, &faces.removed, &faces.refine_removed,
                               num_str.as_deref(), mode, true);
                } else {
                    write_segs(out, b'-', segs, &faces.removed, &faces.refine_removed,
                               num_str.as_deref(), mode, false);
                }
            }
            HunkEvent::Add { content, line_num } => {
                let i = add_idx;
                add_idx += 1;
                let num_str = if *mode != LineNumberMode::None {
                    Some(fmt_add(line_num + 1, w))
                } else { None };
                let (segs, is_excess) = if let Some(pidx) = add_pair[i] {
                    (&pair_diffs[pidx].1 as &Vec<Seg>, false)
                } else {
                    (&pair_diffs[0].0 as &Vec<Seg>, true) // placeholder
                };
                if is_excess {
                    let eu = vec![Seg::Unique(content.clone())];
                    write_segs(out, b'+', &eu, &faces.added, &faces.refine_added,
                               num_str.as_deref(), mode, true);
                } else {
                    write_segs(out, b'+', segs, &faces.added, &faces.refine_added,
                               num_str.as_deref(), mode, false);
                }
            }
            HunkEvent::Passthrough { line } => {
                write_passthrough(out, line);
            }
        }
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mut faces = Faces::default();
    let mut mode = LineNumberMode::None;

    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "-h" | "--help" => { print_help(); process::exit(0); }
            "-V" | "--version" => { eprintln!("diffr {}", VERSION); process::exit(0); }
            "--colors" => {
                i += 1;
                if i >= args.len() { eprintln!("error: missing argument for --colors"); process::exit(255); }
                if let Err(e) = parse_color_spec(&args[i], &mut faces) { eprintln!("{}", e); process::exit(255); }
            }
            "--line-numbers" => {
                if i + 1 < args.len() && (args[i+1] == "compact" || args[i+1] == "aligned") {
                    i += 1;
                    mode = if args[i] == "aligned" { LineNumberMode::Aligned } else { LineNumberMode::Compact };
                } else { mode = LineNumberMode::Compact; }
            }
            _ => { eprintln!("error: unexpected argument: {}", args[i]); process::exit(1); }
        }
        i += 1;
    }

    let stdout = io::stdout();
    let mut out_handle = stdout.lock();
    let mut output: Vec<u8> = Vec::new();
    let stdin = io::stdin();

    let mut in_hunk = false;
    let mut w = 1usize;
    let mut old_line = 0usize;
    let mut new_line = 0usize;
    let mut batch: Vec<HunkEvent> = Vec::new();
    let mut batch_has_content = false;  // has any remove or add

    let do_flush = |output: &mut Vec<u8>, batch: &mut Vec<HunkEvent>, w: usize,
                    faces: &Faces, mode: &LineNumberMode| {
        flush_batch(output, batch, w, faces, mode);
        batch.clear();
    };

    for line in stdin.lock().lines() {
        let line = match line { Ok(l) => l, Err(_) => break };
        let first = line.as_bytes().first().copied();

        if in_hunk {
            match first {
                Some(b' ') => {
                    // Context line - flush current batch first
                    do_flush(&mut output, &mut batch, w, &faces, &mode);

                    let num_str = if mode != LineNumberMode::None {
                        Some(fmt_ctx(old_line + 1, new_line + 1, w))
                    } else { None };
                    write_context(&mut output, &line, num_str.as_deref(), &mode);
                    old_line += 1;
                    new_line += 1;
                }
                Some(b'-') => {
                    batch.push(HunkEvent::Remove { content: line[1..].to_string(), line_num: old_line });
                    old_line += 1;
                }
                Some(b'+') => {
                    batch.push(HunkEvent::Add { content: line[1..].to_string(), line_num: new_line });
                    new_line += 1;
                }
                Some(b'\\') => {
                    // "\ No newline" - just add to batch as passthrough (don't flush)
                    batch.push(HunkEvent::Passthrough { line: line.clone() });
                }
                _ => {
                    // End of hunk
                    do_flush(&mut output, &mut batch, w, &faces, &mode);
                    in_hunk = false;

                    if line.starts_with("@@ ") {
                        if let Some((os, oc, ns, nc)) = parse_hunk(&line) {
                            w = compute_w(os, oc, ns, nc);
                            old_line = os.saturating_sub(1);
                            new_line = ns.saturating_sub(1);
                            batch.clear();
                            in_hunk = true;
                            write_passthrough(&mut output, &line);
                            continue;
                        }
                    }
                    write_passthrough(&mut output, &line);
                }
            }
        } else {
            if line.starts_with("@@ ") {
                if let Some((os, oc, ns, nc)) = parse_hunk(&line) {
                    w = compute_w(os, oc, ns, nc);
                    old_line = os.saturating_sub(1);
                    new_line = ns.saturating_sub(1);
                    batch.clear();
                    in_hunk = true;
                    write_passthrough(&mut output, &line);
                    continue;
                }
            }
            write_passthrough(&mut output, &line);
        }
    }

    // Flush remaining
    if in_hunk {
        do_flush(&mut output, &mut batch, w, &faces, &mode);
    }

    out_handle.write_all(&output).unwrap();
}

fn print_help() {
    let help = include_str!("../assets/help.txt").replace("$VERSION", VERSION);
    println!("{}", help);
}
