        "removed" => &mut faces.removed,
        "refine-added" => &mut faces.refine_added,
        "refine-removed" => &mut faces.refine_removed,
        _ => return Err(format!("unexpected face name: got '{}', expected added|refine-added|removed|refine-removed", face_name)),
    };
