fn parse_attrs(attrs: &str, face: &mut Face) -> Result<(), String> {
    if attrs.is_empty() { return Ok(()); }
    let mut remaining = attrs;
    while !remaining.is_empty() {
        if remaining.starts_with("foreground:") || remaining.starts_with("background:") {
            let is_fg = remaining.starts_with("foreground:");
            let after = if is_fg { &remaining["foreground:".len()..] } else { &remaining["background:".len()..] };
            let (cs, rest) = parse_color_value(after)?;
            let color = parse_color(&cs)?;
            if is_fg { face.foreground = color; } else { face.background = color; }
            remaining = rest;
        } else {
            let (attr, rest) = remaining.find(':').map(|p| (&remaining[..p], &remaining[p+1..]))
                                        .unwrap_or((remaining, ""));
            match attr {
                "none" => { *face = Face::cleared(); }
                "bold" => { face.bold = Some(true); }
                "nobold" => { face.bold = Some(false); }
                "italic" => { face.italic = Some(true); }
                "noitalic" => { face.italic = Some(false); }
                "underline" => { face.underline = Some(true); }
                "nounderline" => { face.underline = Some(false); }
                "dimmed" => { face.dimmed = Some(true); }
                "nodimmed" => { face.dimmed = Some(false); }
                "intense" => { face.intense = true; }
                "nointense" => { face.intense = false; }
                _ => return Err(format!("unexpected attribute name: got '{}', expected foreground|background|italic|noitalic|bold|nobold|dimmed|nodimmed|intense|nointense|underline|nounderline|none", attr)),
            }
            remaining = rest;
        }
    }
    Ok(())
}

fn parse_color_value(s: &str) -> Result<(String, &str), String> {
    let first_colon = s.find(':');
    let candidate = first_colon.map(|p| &s[..p]).unwrap_or(s);
    let rest = first_colon.map(|p| &s[p+1..]).unwrap_or("");
    Ok((candidate.to_string(), rest))
}

fn parse_color(s: &str) -> Result<ColorSpec, String> {
    if s == "none" { return Ok(ColorSpec::None); }
    match s {
        "black" => return Ok(ColorSpec::Ansi(0)),
        "red" => return Ok(ColorSpec::Ansi(1)),
        "green" => return Ok(ColorSpec::Ansi(2)),
        "yellow" => return Ok(ColorSpec::Ansi(3)),
        "blue" => return Ok(ColorSpec::Ansi(4)),
        "magenta" => return Ok(ColorSpec::Ansi(5)),
        "cyan" => return Ok(ColorSpec::Ansi(6)),
        "white" => return Ok(ColorSpec::Ansi(7)),
        _ => {}
    }
    if s.contains(',') {
        let parts: Vec<&str> = s.split(',').collect();
        if parts.len() != 3 {
            return Err(format!("unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{}'", s));
        }
        let r = parse_u8h(parts[0]).ok_or_else(|| format!("unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{}'", s))?;
        let g = parse_u8h(parts[1]).ok_or_else(|| format!("unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{}'", s))?;
        let b = parse_u8h(parts[2]).ok_or_else(|| format!("unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{}'", s))?;
        return Ok(ColorSpec::Rgb(r, g, b));
    }
    let s_trim = s.trim();
    let is_numeric = s_trim.starts_with("0x") || s_trim.starts_with("0X") || s_trim.chars().all(|c| c.is_ascii_digit());
    if is_numeric { return parse_ansi256(s); }
    Err(format!("unexpected color value: unrecognized color name '{}'. Choose from: black, blue, green, red, cyan, magenta, yellow, white", s))
}

fn parse_u8h(s: &str) -> Option<u8> {
    let s = s.trim();
    if s.starts_with("0x") || s.starts_with("0X") { u8::from_str_radix(&s[2..], 16).ok() }
    else { let n: u16 = s.parse().ok()?; if n <= 255 { Some(n as u8) } else { None } }
}

fn parse_ansi256(s: &str) -> Result<ColorSpec, String> {
    let s = s.trim();
    if s.starts_with("0x") || s.starts_with("0X") {
        return u8::from_str_radix(&s[2..], 16).map(ColorSpec::Ansi256)
            .map_err(|_| format!("unexpected color value: unrecognized ansi256 color number, should be '[0-255]' (or a hex number), but is '{}'", s));
    }
    if !s.chars().all(|c| c.is_ascii_digit()) {
        return Err(format!("unexpected color value: unrecognized color name '{}'. Choose from: black, blue, green, red, cyan, magenta, yellow, white", s));
    }
    let n: u64 = s.parse().map_err(|_| format!("unexpected color value: unrecognized ansi256 color number, should be '[0-255]' (or a hex number), but is '{}'", s))?;
    if n <= 255 { Ok(ColorSpec::Ansi256(n as u8)) }
    else { Err(format!("unexpected color value: unrecognized ansi256 color number, should be '[0-255]' (or a hex number), but is '{}'", s)) }
