use std::io::{self, BufRead, Write};
use std::process;

const VERSION: &str = "0.1.5";

// ============ Color/Face types ============

#[derive(Debug, Clone)]
struct Face {
    bold: Option<bool>,
    dimmed: Option<bool>,
    italic: Option<bool>,
    underline: Option<bool>,
    intense: bool,
    foreground: ColorSpec,
    background: ColorSpec,
}

#[derive(Debug, Clone, PartialEq)]
enum ColorSpec { None, Ansi(u8), Ansi256(u8), Rgb(u8, u8, u8) }

impl Face {
    fn cleared() -> Self {
        Face { bold: None, dimmed: None, italic: None, underline: None, intense: false,
               foreground: ColorSpec::None, background: ColorSpec::None }
    }
    fn write_ansi(&self, out: &mut Vec<u8>) {
        if self.bold == Some(true) { out.extend_from_slice(b"\x1b[1m"); }
        if self.dimmed == Some(true) { out.extend_from_slice(b"\x1b[2m"); }
        if self.italic == Some(true) { out.extend_from_slice(b"\x1b[3m"); }
        if self.underline == Some(true) { out.extend_from_slice(b"\x1b[4m"); }
        match &self.foreground {
            ColorSpec::None => {}
            ColorSpec::Ansi(c) => if self.intense { write!(out, "\x1b[38;5;{}m", c+8).unwrap(); }
                                   else { write!(out, "\x1b[{}m", 30+c).unwrap(); }
            ColorSpec::Ansi256(c) => write!(out, "\x1b[38;5;{}m", c).unwrap(),
            ColorSpec::Rgb(r,g,b) => write!(out, "\x1b[38;2;{};{};{}m", r,g,b).unwrap(),
        }
        match &self.background {
            ColorSpec::None => {}
            ColorSpec::Ansi(c) => if self.intense { write!(out, "\x1b[48;5;{}m", c+8).unwrap(); }
                                   else { write!(out, "\x1b[{}m", 40+c).unwrap(); }
            ColorSpec::Ansi256(c) => write!(out, "\x1b[48;5;{}m", c).unwrap(),
            ColorSpec::Rgb(r,g,b) => write!(out, "\x1b[48;2;{};{};{}m", r,g,b).unwrap(),
        }
    }
}

fn default_added() -> Face { Face { bold: None, dimmed: None, italic: None, underline: None,
    intense: false, foreground: ColorSpec::Ansi(2), background: ColorSpec::None } }
fn default_removed() -> Face { Face { bold: None, dimmed: None, italic: None, underline: None,
    intense: false, foreground: ColorSpec::Ansi(1), background: ColorSpec::None } }
fn default_refine_added() -> Face { Face { bold: Some(true), dimmed: None, italic: None, underline: None,
    intense: false, foreground: ColorSpec::Rgb(255,255,255), background: ColorSpec::Ansi(2) } }
fn default_refine_removed() -> Face { Face { bold: Some(true), dimmed: None, italic: None, underline: None,
    intense: false, foreground: ColorSpec::Rgb(255,255,255), background: ColorSpec::Ansi(1) } }

// ============ Color spec parsing ============

fn parse_color_spec(spec: &str, faces: &mut Faces) -> Result<(), String> {
    let mut parts = spec.splitn(2, ':');
    let face_name = parts.next().unwrap_or("");
    let attrs_str = parts.next().unwrap_or("");
    let face = match face_name {
        "added" => &mut faces.added,
        "removed" => &mut faces.removed,
        "refine-added" => &mut faces.refine_added,
        "refine-removed" => &mut faces.refine_removed,
        _ => return Err(format!("unexpected face name: got '{}', expected added|refine-added|removed|refine-removed", face_name)),
    };
    parse_attrs(attrs_str, face)
}

fn parse_attrs(attrs: &str, face: &mut Face) -> Result<(), String> {
    if attrs.is_empty() { return Ok(()); }
    let mut remaining = attrs;
    while !remaining.is_empty() {
        if remaining.starts_with("foreground:") || remaining.starts_with("background:") {
            let is_fg = remaining.starts_with("foreground:");
            let after = if is_fg { &remaining["foreground:".len()..] } else { &remaining["background:".len()..] };
            let (cs, rest) = parse_color_value(after)?;
            let color = parse_color(&cs)?;
            if is_fg { face.foreground = color; } else { face.background = color; }
            remaining = rest;
        } else {
            let (attr, rest) = remaining.find(':').map(|p| (&remaining[..p], &remaining[p+1..]))
                                        .unwrap_or((remaining, ""));
            match attr {
                "none" => { *face = Face::cleared(); }
                "bold" => { face.bold = Some(true); }
                "nobold" => { face.bold = Some(false); }
                "italic" => { face.italic = Some(true); }
                "noitalic" => { face.italic = Some(false); }
                "underline" => { face.underline = Some(true); }
                "nounderline" => { face.underline = Some(false); }
                "dimmed" => { face.dimmed = Some(true); }
                "nodimmed" => { face.dimmed = Some(false); }
                "intense" => { face.intense = true; }
                "nointense" => { face.intense = false; }
                _ => return Err(format!("unexpected attribute name: got '{}', expected foreground|background|italic|noitalic|bold|nobold|dimmed|nodimmed|intense|nointense|underline|nounderline|none", attr)),
            }
            remaining = rest;
        }
    }
    Ok(())
}

fn parse_color_value(s: &str) -> Result<(String, &str), String> {
    let first_colon = s.find(':');
    let candidate = first_colon.map(|p| &s[..p]).unwrap_or(s);
    let rest = first_colon.map(|p| &s[p+1..]).unwrap_or("");
    Ok((candidate.to_string(), rest))
}

fn parse_color(s: &str) -> Result<ColorSpec, String> {
    if s == "none" { return Ok(ColorSpec::None); }
    match s {
        "black" => return Ok(ColorSpec::Ansi(0)),
        "red" => return Ok(ColorSpec::Ansi(1)),
        "green" => return Ok(ColorSpec::Ansi(2)),
        "yellow" => return Ok(ColorSpec::Ansi(3)),
        "blue" => return Ok(ColorSpec::Ansi(4)),
        "magenta" => return Ok(ColorSpec::Ansi(5)),
        "cyan" => return Ok(ColorSpec::Ansi(6)),
        "white" => return Ok(ColorSpec::Ansi(7)),
        _ => {}
    }
    if s.contains(',') {
        let parts: Vec<&str> = s.split(',').collect();
        if parts.len() != 3 {
            return Err(format!("unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{}'", s));
        }
        let r = parse_u8h(parts[0]).ok_or_else(|| format!("unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{}'", s))?;
        let g = parse_u8h(parts[1]).ok_or_else(|| format!("unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{}'", s))?;
        let b = parse_u8h(parts[2]).ok_or_else(|| format!("unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{}'", s))?;
        return Ok(ColorSpec::Rgb(r, g, b));
    }
    let s_trim = s.trim();
    let is_numeric = s_trim.starts_with("0x") || s_trim.starts_with("0X") || s_trim.chars().all(|c| c.is_ascii_digit());
    if is_numeric { return parse_ansi256(s); }
    Err(format!("unexpected color value: unrecognized color name '{}'. Choose from: black, blue, green, red, cyan, magenta, yellow, white", s))
}

fn parse_u8h(s: &str) -> Option<u8> {
    let s = s.trim();
    if s.starts_with("0x") || s.starts_with("0X") { u8::from_str_radix(&s[2..], 16).ok() }
    else { let n: u16 = s.parse().ok()?; if n <= 255 { Some(n as u8) } else { None } }
}

fn parse_ansi256(s: &str) -> Result<ColorSpec, String> {
    let s = s.trim();
    if s.starts_with("0x") || s.starts_with("0X") {
        return u8::from_str_radix(&s[2..], 16).map(ColorSpec::Ansi256)
            .map_err(|_| format!("unexpected color value: unrecognized ansi256 color number, should be '[0-255]' (or a hex number), but is '{}'", s));
    }
    if !s.chars().all(|c| c.is_ascii_digit()) {
        return Err(format!("unexpected color value: unrecognized color name '{}'. Choose from: black, blue, green, red, cyan, magenta, yellow, white", s));
    }
    let n: u64 = s.parse().map_err(|_| format!("unexpected color value: unrecognized ansi256 color number, should be '[0-255]' (or a hex number), but is '{}'", s))?;
    if n <= 255 { Ok(ColorSpec::Ansi256(n as u8)) }
    else { Err(format!("unexpected color value: unrecognized ansi256 color number, should be '[0-255]' (or a hex number), but is '{}'", s)) }
}

struct Faces { added: Face, removed: Face, refine_added: Face, refine_removed: Face }
impl Faces {
    fn default() -> Self { Faces { added: default_added(), removed: default_removed(),
                                   refine_added: default_refine_added(), refine_removed: default_refine_removed() } }
}

#[derive(Debug, Clone, PartialEq)]
enum LineNumberMode { None, Compact, Aligned }

// ============ Tokenizer ============

fn tokenize(s: &str) -> Vec<String> {
    if s.is_empty() { return vec![]; }
    let mut tokens = Vec::new();
    let mut current = String::new();
    let mut cur_ws: Option<bool> = None;
    for c in s.chars() {
        let is_ws = c.is_whitespace();
        match cur_ws {
            None => { current.push(c); cur_ws = Some(is_ws); }
            Some(cw) if cw == is_ws => { current.push(c); }
            Some(_) => { tokens.push(current.clone()); current = c.to_string(); cur_ws = Some(is_ws); }
        }
    }
    if !current.is_empty() { tokens.push(current); }
    tokens
}

// ============ LCS ============

fn compute_lcs(s1: &[String], s2: &[String]) -> (Vec<bool>, Vec<bool>) {
    let (n, m) = (s1.len(), s2.len());
    if n == 0 || m == 0 { return (vec![false; n], vec![false; m]); }
    let mut dp = vec![vec![0u32; m+1]; n+1];
    for i in 1..=n {
        for j in 1..=m {
            dp[i][j] = if s1[i-1] == s2[j-1] { dp[i-1][j-1]+1 } else { dp[i-1][j].max(dp[i][j-1]) };
        }
    }
    let mut in1 = vec![false; n]; let mut in2 = vec![false; m];
    let (mut i, mut j) = (n, m);
    while i > 0 && j > 0 {
        if s1[i-1] == s2[j-1] { in1[i-1]=true; in2[j-1]=true; i-=1; j-=1; }
        else if dp[i-1][j] >= dp[i][j-1] { i-=1; } else { j-=1; }
    }
    (in1, in2)
}

// ============ Display segments ============

#[derive(Debug, Clone)]
enum Seg { Common(String), Unique(String) }

// Build segments from tokens + in_lcs flags, merging adjacent same-type
fn build_segs(tokens: &[String], in_lcs: &[bool]) -> Vec<Seg> {
    let mut segs: Vec<Seg> = Vec::new();
    for (i, tok) in tokens.iter().enumerate() {
        if in_lcs[i] {
            if let Some(Seg::Common(ref mut s)) = segs.last_mut() { s.push_str(tok); }
            else { segs.push(Seg::Common(tok.clone())); }
        } else {
            if let Some(Seg::Unique(ref mut s)) = segs.last_mut() { s.push_str(tok); }
            else { segs.push(Seg::Unique(tok.clone())); }
        }
    }
    segs
}

// ============ Hunk-level diff ============

/// Result for a single line in the batch
struct LineDiff {
    segs: Vec<Seg>,
    trailing: bool,  // should show trailing face RST after last unique seg
}

/// Process a batch of removes and adds using hunk-level token LCS.
/// Returns (rm_diffs, add_diffs)
fn diff_batch(removes: &[String], adds: &[String]) -> (Vec<LineDiff>, Vec<LineDiff>) {
    if removes.is_empty() && adds.is_empty() { return (vec![], vec![]); }

    // Collect all tokens with line indices
    let mut rm_tokens: Vec<String> = Vec::new();
    let mut rm_line_map: Vec<usize> = Vec::new(); // which remove line each token belongs to
    for (li, line) in removes.iter().enumerate() {
        for t in tokenize(line) { rm_tokens.push(t); rm_line_map.push(li); }
    }

    let mut add_tokens: Vec<String> = Vec::new();
    let mut add_line_map: Vec<usize> = Vec::new();
    for (li, line) in adds.iter().enumerate() {
        for t in tokenize(line) { add_tokens.push(t); add_line_map.push(li); }
    }

    // Compute LCS on all tokens
    let (in_rm, in_add) = compute_lcs(&rm_tokens, &add_tokens);

    // Distribute tokens back to lines and build segments
    let n_rm = removes.len();
    let n_add = adds.len();

    let mut rm_diffs: Vec<LineDiff> = Vec::with_capacity(n_rm);
    let mut add_diffs: Vec<LineDiff> = Vec::with_capacity(n_add);

    // Process each remove line
    for li in 0..n_rm {
        let line_tokens: Vec<(String, bool)> = rm_tokens.iter().zip(in_rm.iter())
            .enumerate()
            .filter(|(i, _)| rm_line_map[*i] == li)
            .map(|(_, (t, c))| (t.clone(), *c))
            .collect();

        let tokens: Vec<String> = line_tokens.iter().map(|(t,_)| t.clone()).collect();
        let in_lcs: Vec<bool> = line_tokens.iter().map(|(_,c)| *c).collect();
        let segs = build_segs(&tokens, &in_lcs);

        // Trailing rule: shown if this is the LAST remove AND last seg is unique
        let is_last = li == n_rm - 1;
        let last_is_unique = matches!(segs.last(), Some(Seg::Unique(_)));
        let trailing = is_last && last_is_unique;

        rm_diffs.push(LineDiff { segs, trailing });
    }

    // Process each add line
    for li in 0..n_add {
        let line_tokens: Vec<(String, bool)> = add_tokens.iter().zip(in_add.iter())
            .enumerate()
            .filter(|(i, _)| add_line_map[*i] == li)
            .map(|(_, (t, c))| (t.clone(), *c))
            .collect();

        let tokens: Vec<String> = line_tokens.iter().map(|(t,_)| t.clone()).collect();
        let in_lcs: Vec<bool> = line_tokens.iter().map(|(_,c)| *c).collect();
        let segs = build_segs(&tokens, &in_lcs);

        let is_last = li == n_add - 1;
        let last_is_unique = matches!(segs.last(), Some(Seg::Unique(_)));
        let trailing = is_last && last_is_unique;

        add_diffs.push(LineDiff { segs, trailing });
    }

    (rm_diffs, add_diffs)
}

// ============ Line output functions ============

/// Write a diff line (removed or added) to output
fn write_diff_line(
    out: &mut Vec<u8>,
    prefix: u8,
    diff: &LineDiff,
    face: &Face,
    refine_face: &Face,
    num_str: Option<&str>,
    mode: &LineNumberMode,
) {
    // Line number block
    if let Some(ns) = num_str {
        out.extend_from_slice(b"\x1b[0m");
        face.write_ansi(out);
        out.extend_from_slice(ns.as_bytes());
        out.extend_from_slice(b"\x1b[0m");
        if *mode == LineNumberMode::Aligned { out.push(b'\t'); }
    }

    let segs = &diff.segs;

    if segs.is_empty() {
        // Empty line content
        out.extend_from_slice(b"\x1b[0m");
        face.write_ansi(out);
        out.push(prefix);
        out.extend_from_slice(b"\x1b[0m");
        out.extend_from_slice(b"\x1b[0m\x1b[41m\x1b[0m");
    } else {
        // Check if first seg is Common with leading whitespace -> merge with prefix
        let leading_ws_len = if let Seg::Common(s) = &segs[0] {
            s.find(|c: char| !c.is_whitespace()).unwrap_or(s.len())
        } else { 0 };

        if leading_ws_len > 0 {
            // Merge prefix with leading whitespace
            out.extend_from_slice(b"\x1b[0m");
            face.write_ansi(out);
            out.push(prefix);
            if let Seg::Common(s) = &segs[0] {
                out.extend_from_slice(s[..leading_ws_len].as_bytes());
            }
            out.extend_from_slice(b"\x1b[0m");

            // Output remaining (possibly split first seg + rest)
            let first_remainder = if let Seg::Common(s) = &segs[0] {
                if leading_ws_len < s.len() { Some(Seg::Common(s[leading_ws_len..].to_string())) } else { None }
            } else { None };

            let eff_segs: Vec<&Seg>;
            let rem_vec: Vec<Seg>;
            if let Some(ref rem) = first_remainder {
                rem_vec = std::iter::once(rem).chain(segs[1..].iter()).cloned().collect();
                eff_segs = rem_vec.iter().collect();
            } else {
                eff_segs = segs[1..].iter().collect();
            }

            write_content_segs(out, &eff_segs, face, refine_face, diff.trailing);
        } else {
            // Prefix alone
            out.extend_from_slice(b"\x1b[0m");
            face.write_ansi(out);
            out.push(prefix);
            out.extend_from_slice(b"\x1b[0m");

            let eff_segs: Vec<&Seg> = segs.iter().collect();
            write_content_segs(out, &eff_segs, face, refine_face, diff.trailing);
        }
    }
    out.push(b'\n');
}

fn write_content_segs(out: &mut Vec<u8>, segs: &[&Seg], face: &Face, refine_face: &Face, trailing: bool) {
    let last_idx = if segs.is_empty() { return; } else { segs.len() - 1 };
    for (i, seg) in segs.iter().enumerate() {
        match seg {
            Seg::Common(s) => {
                out.extend_from_slice(b"\x1b[0m");
                face.write_ansi(out);
                out.extend_from_slice(s.as_bytes());
                out.extend_from_slice(b"\x1b[0m");
            }
            Seg::Unique(s) => {
                out.extend_from_slice(b"\x1b[0m");
                refine_face.write_ansi(out);
                out.extend_from_slice(s.as_bytes());
                out.extend_from_slice(b"\x1b[0m");
            }
        }
        if i == last_idx && trailing {
            if let Seg::Unique(_) = seg {
                out.extend_from_slice(b"\x1b[0m");
                face.write_ansi(out);
                out.extend_from_slice(b"\x1b[0m");
            }
        }
    }
}

/// Write a context line
fn write_context(out: &mut Vec<u8>, full_line: &str, num_str: Option<&str>, mode: &LineNumberMode) {
    if let Some(ns) = num_str {
        out.extend_from_slice(ns.as_bytes());
        if *mode == LineNumberMode::Aligned {
            out.push(b'\t');
            out.extend_from_slice(b"\x1b[0m");
        } else {
            out.extend_from_slice(b"\x1b[0m");
        }
    } else {
        out.extend_from_slice(b"\x1b[0m");
    }
    out.extend_from_slice(full_line.as_bytes());
    out.extend_from_slice(b"\x1b[0m");
    out.push(b'\n');
}

fn write_passthrough(out: &mut Vec<u8>, line: &str) {
    out.extend_from_slice(b"\x1b[0m");
    out.extend_from_slice(line.as_bytes());
    out.extend_from_slice(b"\x1b[0m");
    out.push(b'\n');
}

// ============ Line number formatting ============

fn num_digits(n: usize) -> usize { if n == 0 { 1 } else { n.to_string().len() } }
fn compute_w(os: usize, oc: usize, ns: usize, nc: usize) -> usize {
    num_digits(os + oc).max(num_digits(ns + nc))
}

fn fmt_ctx(l: usize, r: usize, w: usize) -> String {
    if l == r { format!("{:>width$}", r, width=2*w+1) }
    else { format!("{:>width$} {:>width$}", l, r, width=w) }
}
fn fmt_rm(l: usize, w: usize) -> String { format!("{:>width$} {:width$}", l, "", width=w) }
fn fmt_add(r: usize, w: usize) -> String { format!("{:width$} {:>width$}", "", r, width=w) }

// ============ Hunk parsing ============

fn parse_hunk(line: &str) -> Option<(usize, usize, usize, usize)> {
    if !line.starts_with("@@ ") { return None; }
    let after = &line[3..];
    let end = after.find(" @@")?;
    let nums = &after[..end];
    let mut parts = nums.split_whitespace();
    let op = parts.next()?.trim_start_matches('-');
    let np = parts.next()?.trim_start_matches('+');
    let (os, oc) = parse_range(op)?;
    let (ns, nc) = parse_range(np)?;
    Some((os, oc, ns, nc))
}

fn parse_range(s: &str) -> Option<(usize, usize)> {
    if let Some(c) = s.find(',') { Some((s[..c].parse().ok()?, s[c+1..].parse().ok()?)) }
    else { Some((s.parse().ok()?, 1)) }
}

// ============ Batch events ============

#[derive(Debug)]
enum HunkEvent {
    Remove { content: String, line_num: usize },
    Add { content: String, line_num: usize },
    Passthrough { line: String },
}

fn flush_batch(out: &mut Vec<u8>, events: &[HunkEvent], w: usize, faces: &Faces, mode: &LineNumberMode) {
    if events.is_empty() { return; }

    // Collect removes and adds
    let removes: Vec<(&str, usize)> = events.iter().filter_map(|e| {
        if let HunkEvent::Remove { content, line_num } = e { Some((content.as_str(), *line_num)) } else { None }
    }).collect();
    let adds: Vec<(&str, usize)> = events.iter().filter_map(|e| {
        if let HunkEvent::Add { content, line_num } = e { Some((content.as_str(), *line_num)) } else { None }
    }).collect();

    let rm_contents: Vec<String> = removes.iter().map(|(s,_)| s.to_string()).collect();
    let add_contents: Vec<String> = adds.iter().map(|(s,_)| s.to_string()).collect();

    let (rm_diffs, add_diffs) = diff_batch(&rm_contents, &add_contents);

    // Track indices for rm and add
    let mut rm_idx = 0usize;
    let mut add_idx = 0usize;

    for event in events {
        match event {
            HunkEvent::Remove { content: _, line_num } => {
                let num_str = if *mode != LineNumberMode::None { Some(fmt_rm(*line_num + 1, w)) } else { None };
                write_diff_line(out, b'-', &rm_diffs[rm_idx], &faces.removed, &faces.refine_removed,
                                num_str.as_deref(), mode);
                rm_idx += 1;
            }
            HunkEvent::Add { content: _, line_num } => {
                let num_str = if *mode != LineNumberMode::None { Some(fmt_add(*line_num + 1, w)) } else { None };
                write_diff_line(out, b'+', &add_diffs[add_idx], &faces.added, &faces.refine_added,
                                num_str.as_deref(), mode);
                add_idx += 1;
            }
            HunkEvent::Passthrough { line } => {
                write_passthrough(out, line);
            }
        }
    }
}

// ============ Main ============

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mut faces = Faces::default();
    let mut mode = LineNumberMode::None;

    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "-h" | "--help" => { print_help(); process::exit(0); }
            "-V" | "--version" => { eprintln!("diffr {}", VERSION); process::exit(0); }
            "--colors" => {
                i += 1;
                if i >= args.len() { eprintln!("error: missing argument for --colors"); process::exit(255); }
                if let Err(e) = parse_color_spec(&args[i], &mut faces) { eprintln!("{}", e); process::exit(255); }
            }
            "--line-numbers" => {
                if i+1 < args.len() && (args[i+1] == "compact" || args[i+1] == "aligned") {
                    i += 1;
                    mode = if args[i] == "aligned" { LineNumberMode::Aligned } else { LineNumberMode::Compact };
                } else { mode = LineNumberMode::Compact; }
            }
            _ => { eprintln!("error: unexpected argument: {}", args[i]); process::exit(1); }
        }
        i += 1;
    }

    let stdout = io::stdout();
    let mut out_handle = stdout.lock();
    let mut output: Vec<u8> = Vec::new();
    let stdin = io::stdin();

    let mut in_hunk = false;
    let mut w = 1usize;
    let mut old_line = 0usize;
    let mut new_line = 0usize;
    let mut batch: Vec<HunkEvent> = Vec::new();

    let do_flush = |out: &mut Vec<u8>, batch: &mut Vec<HunkEvent>, w: usize, faces: &Faces, mode: &LineNumberMode| {
        flush_batch(out, batch, w, faces, mode);
        batch.clear();
    };

    for line in stdin.lock().lines() {
        let line = match line { Ok(l) => l, Err(_) => break };
        let first = line.as_bytes().first().copied();

        if in_hunk {
            match first {
                Some(b' ') => {
                    do_flush(&mut output, &mut batch, w, &faces, &mode);
                    let num_str = if mode != LineNumberMode::None { Some(fmt_ctx(old_line+1, new_line+1, w)) } else { None };
                    write_context(&mut output, &line, num_str.as_deref(), &mode);
                    old_line += 1; new_line += 1;
                }
                Some(b'-') => {
                    batch.push(HunkEvent::Remove { content: line[1..].to_string(), line_num: old_line });
                    old_line += 1;
                }
                Some(b'+') => {
                    batch.push(HunkEvent::Add { content: line[1..].to_string(), line_num: new_line });
                    new_line += 1;
                }
                Some(b'\\') => {
                    // "\ No newline" - passthrough without flushing
                    batch.push(HunkEvent::Passthrough { line: line.clone() });
                }
                _ => {
                    do_flush(&mut output, &mut batch, w, &faces, &mode);
                    in_hunk = false;
                    if line.starts_with("@@ ") {
                        if let Some((os, oc, ns, nc)) = parse_hunk(&line) {
                            w = compute_w(os, oc, ns, nc);
                            old_line = os.saturating_sub(1);
                            new_line = ns.saturating_sub(1);
                            batch.clear(); in_hunk = true;
                            write_passthrough(&mut output, &line);
                            continue;
                        }
                    }
                    write_passthrough(&mut output, &line);
                }
            }
        } else {
            if line.starts_with("@@ ") {
                if let Some((os, oc, ns, nc)) = parse_hunk(&line) {
                    w = compute_w(os, oc, ns, nc);
                    old_line = os.saturating_sub(1);
                    new_line = ns.saturating_sub(1);
                    batch.clear(); in_hunk = true;
                    write_passthrough(&mut output, &line);
                    continue;
                }
            }
            write_passthrough(&mut output, &line);
        }
    }

    if in_hunk { do_flush(&mut output, &mut batch, w, &faces, &mode); }
    out_handle.write_all(&output).unwrap();
}

fn print_help() {
    let help = include_str!("../assets/help.txt").replace("$VERSION", VERSION);
    print!("{}", help);
}
