fn compute_paired(n_rm: usize, n_add: usize) -> (Vec<bool>, Vec<bool>) {
    let n_pairs = n_rm.min(n_add);
    let mut rm_paired = vec![false; n_rm];
    let mut add_paired = vec![false; n_add];
    if n_pairs > 0 {
        // First n_pairs-1 from top
        for i in 0..n_pairs-1 {
            rm_paired[i] = true;
            add_paired[i] = true;
        }
        // Last pair
        rm_paired[n_rm-1] = true;
        add_paired[n_add-1] = true;
